		"Active coupons" => "קופונים פעילים",
		"Active now: %s" => "פעיל כרגע: %s",
		"ActiveTrail" => "ActiveTrail",
		"ActiveTrail API key" => "מפתח API של ActiveTrail",
		"Add" => "הוספה",
		"Add %s to the cart" => "הוספת %s לסל",
		"Add a \"Privacy settings\" link to the footer" => "הוספת קישור \"הגדרות פרטיות\" לפוטר",
		"Add a block" => "הוספת בלוק",
		"Add a brand" => "הוספת מותג",
