		"Add a link" => "הוספת קישור",
		"Add a placement" => "הוספת מיקום",
		"Add a product" => "הוספת מוצר",
		"Add a region" => "הוספת אזור",
		"Add a tab" => "הוספת טאב",
		"Add all to cart" => "הוסף הכל לסל",
		"Add an address" => "הוספת כתובת",
		"Add an attribute used for variations (for example: colour), save, and its values appear here." => "הוסף למוצר תכונה שמשמשת לווריאציות (למשל: צבע), שמור, והערכים שלה יופיעו כאן.",
		"Add as well" => "הוספה בנוסף",
		"Add images" => "הוספת תמונות",
		"Add it as a synonym" => "הוספה כמילה נרדפת",
		"Add redirect" => "הוספת הפניה",
		"Add rule" => "הוספת כלל",
		"Add these products as well, or empty the cart and add only them?" => "להוסיף את המוצרים האלה בנוסף, או לרוקן את הסל ולהוסיף רק אותם?",
		"Add to cart" => "הוספה לסל",
		"Add to cart button" => "כפתור הוספה לסל",
		"Add to cart button — mobile" => "כפתור הוספה לסל — מובייל",
		"Add-to-cart area" => "אזור ההוספה לסל",
		"Added" => "נוסף",
		"Added to cart" => "נוסף לסל",
		"Additional information" => "מידע נוסף",
		"Additional phone" => "טלפון נוסף",
		"Additional phone (optional)" => "טלפון נוסף (אופציונלי)",
		"Address" => "כתובת",
		"Address changes" => "שינויי כתובת",
		"Address fields" => "שדות כתובת",
		"Address removed." => "הכתובת הוסרה.",
		"Address saved." => "הכתובת נשמרה.",
		"Addresses that answered 404, how often, and where the visitor came from. Entries older than 30 days clear themselves." => "כתובות שהחזירו 404, כמה פעמים, ומאיפה הגיע המבקר. רשומות בנות יותר מ-30 יום נמחקות מעצמן.",
		"Addresses that never count" => "כתובות שלא נספרות",
		"Admin → Data streams → the stream → Measurement Protocol API secrets. Lets the server report a purchase the browser never did." => "Admin ← Data streams ← הזרם ← Measurement Protocol API secrets. מאפשר לשרת לדווח רכישה שהדפדפן לא דיווח.",
		"Administrators" => "מנהלי מערכת",
		"Administrators and shop managers" => "מנהלי מערכת ומנהלי חנות",
		"Ads Manager → Conversions → API keys. Stays on the server; the browser only ever sees the pixel id." => "Ads Manager ← המרות ← מפתחות API. נשאר בשרת; הדפדפן רואה רק את מזהה הפיקסל.",
		"Ads Manager → Conversions → the data source you created for the website." => "Ads Manager ← המרות ← מקור הנתונים שיצרת לאתר.",
		"Advanced Consent Mode: load Google tags before consent, in denied state (cookieless pings)" => "Consent Mode מתקדם: טעינת תגי גוגל לפני ההסכמה, במצב דחוי (פינגים ללא עוגיות)",
		"After a conversion, remove the picture it replaced and its old sizes — unless that name is written somewhere on the site, in which case it is always kept." => "אחרי המרה, למחוק את התמונה שהוחלפה ואת הגדלים הישנים שלה — אלא אם השם הזה כתוב במקום כלשהו באתר, ואז הוא תמיד נשמר.",
		"After a conversion, remove the picture it replaced and its old sizes — unless that name is written somewhere on the site, in which case it is always kept. Clearing is what gives up the way back." => "אחרי המרה, להסיר את התמונה שהוחלפה ואת הגדלים הישנים שלה — אלא אם השם הזה כתוב במקום כלשהו באתר, ואז הוא תמיד נשמר. הניקוי הוא מה שמוותר על הדרך חזרה.",
		"After a material change to the policy or the tags, every visitor should choose again. Editing the policy page does this by itself; this button does it without an edit." => "אחרי שינוי מהותי במדיניות או בתגים, כל מבקר צריך לבחור מחדש. עריכת עמוד המדיניות עושה זאת לבד; הכפתור הזה עושה זאת בלי עריכה.",
		"After adding to cart" => "אחרי הוספה לסל",
		"After the cart items" => "אחרי המוצרים שבסל",
		"After the tabs" => "אחרי הטאבים",
		"Against yesterday, up to the same hour." => "מול אתמול, עד אותה שעה.",
		"Airy" => "אוורירי",
		"Aligned to the side" => "מיושר לצד",
		"Aligned to the start" => "מיושר להתחלה",
		"Alignment" => "יישור",
		"Alignment (desktop)" => "יישור (דסקטופ)",
		"Alignment (mobile)" => "יישור (מובייל)",
		"All %d results" => "כל %d התוצאות",
		"All at once" => "הכל יחד",
		"All branches" => "כל הסניפים",
		"All brands" => "לכל המותגים",
		"All presses" => "כל הלחיצות",
		"All products" => "כל המוצרים",
		"All the statistics" => "לכל הסטטיסטיקה",
		"All time" => "כל הזמן",
		"Almost nobody completed the checkout %s" => "כמעט אף אחד לא השלים את הקופה %s",
		"Along the text direction" => "לפי כיוון הכתיבה",
		"Already WebP" => "כבר ב‑WebP",
		"Already have an account?" => "כבר יש לך חשבון?",
		"Already have an account? Quick sign-in" => "כבר יש לך חשבון? התחברות מהירה",
		"Already in the table" => "כבר בטבלה",
		"Also answers to" => "מילים נרדפות",
		"Also controls which fields the signup popup shows on the site." => "קובע גם אילו שדות יוצגו בחלון ההרשמה באתר.",
		"Also search" => "לחפש גם ב",
		"Always above everything on the page, edge to edge. Each brand uploads a desktop picture and, if it likes, one for phones." => "תמיד מעל הכל בעמוד, מקצה לקצה. כל מותג מעלה תמונה לדסקטופ, ואם רוצה — גם לנייד.",
		"Always fill the frame (crop)" => "תמיד ממלאת את המסגרת (חיתוך)",
		"Always hidden" => "מוסתר תמיד",
		"Always on" => "תמיד פעיל",
		"Always visible" => "תמיד מוצג",
		"Always whole" => "תמיד במלואה",
		"Amount off" => "הנחה בסכום",
		"An Apple Developer account is needed (99\$ a year, the client's):" => "נדרש חשבון Apple Developer (99\$ לשנה, של הלקוח):",
		"An account with no phone number on file is let through with a warning rather than shut out of the site it runs. Add a mobile number to each staff profile." => "חשבון שאין לו מספר טלפון רשום ייכנס עם אזהרה, ולא ייחסם מהאתר שהוא מנהל. יש להוסיף מספר נייד לפרופיל של כל איש צוות.",
		"An add button on each result" => "כפתור הוספה על כל תוצאה",
		"An approved Twilio content template with {{1}} for the product name and {{2}} for the product link." => "תבנית תוכן מאושרת ב-Twilio שכוללת {{1}} עבור שם המוצר ו-{{2}} עבור הקישור למוצר.",
		"An email and a password are both needed." => "צריך גם מייל וגם סיסמא.",
		"An empty column" => "עמודה ריקה",
		"An empty parcel: the base price." => "חבילה ריקה: מחיר הבסיס.",
		"An enlarged tile fills the width on a phone unless you tick the box." => "אריח מוגדל תופס את כל הרוחב במובייל, אלא אם מסמנים את התיבה.",
		"An invite link to the store's group, for the join widget." => "קישור הזמנה לקבוצה של החנות, עבור ווידג׳ט ההצטרפות.",
		"And leftwards, in Hebrew" => "ובעברית — שמאלה",
		"Announcement bar" => "בר הודעות",
		"Another domain" => "דומיין אחר",
		"Another page" => "עמוד אחר",
		"Answer" => "תשובה",
		"Answering %s" => "בתגובה ל־%s",
		"Any questions?" => "יש לך שאלה?",
		"Apartment" => "מספר דירה",
		"Apartment is required" => "דירה — שדה חובה",
		"App ID" => "App ID",
