		"Automatic fills the frame when the crop is slight and shows the picture whole when more than about an eighth of it would be cut — landscape photos in an upright frame, for instance." => "אוטומטי ממלא את המסגרת כשהחיתוך קל, ומציג את התמונה במלואה כשהיה נחתך ממנה יותר מכשמינית, למשל תמונות לרוחב במסגרת גבוהה.",
