		"Autoplay on the product page — no play button, hover shows the zoom plus. Off: a frozen frame with a play button; a click plays it in place." => "ניגון אוטומטי בדף המוצר — בלי כפתור פליי, ריחוף מציג את הפלוס להגדלה. כבוי: פריים קפוא עם כפתור פליי; לחיצה מנגנת אותו במקום.",
