		"Colours, rotation speed and whether the bar shows at all are in the Customizer." => "הצבעים, מהירות ההחלפה והאם הבר מוצג בכלל — בהתאמה אישית.",
		"Column %d: hide on phones" => "עמודה %d: הסתרה בטלפון",
		"Column headings" => "כותרות העמודות",
		"Column one is the old address, column two the new one, an optional third column the type. CSV or XLSX; a header row is skipped on its own. Nothing is written before you approve the preview." => "עמודה ראשונה — הכתובת הישנה, שנייה — החדשה, ושלישית (רשות) — הסוג. CSV או XLSX; שורת כותרת מדולגת אוטומטית. שום דבר לא נכתב לפני אישור התצוגה המקדימה.",
		"Comes off in the cart once two or more of the bundle are in it, and recalculates itself if one is taken out." => "יורדת בסל ברגע ששני פריטים או יותר מהחבילה נמצאים בו, ומחושבת מחדש אם מסירים אחד.",
		"Comma-separated product IDs, shown in this order." => "מזהי מוצרים מופרדים בפסיקים, מוצגים בסדר הזה.",
		"Comment count" => "מספר תגובות",
