		"Comments reflect their writers alone. Keep it kind — offensive or promotional comments are removed. Your email stays private and is never shown." => "התגובות משקפות את דעת כותביהן בלבד. שמרו על שיח מכבד — תגובות פוגעניות או פרסומיות יוסרו. כתובת האימייל שלכם נשארת אצלנו ולא תוצג באתר.",
