		"Conversions API key" => "מפתח Conversions API",
		"Convert" => "המרה",
		"Convert %d pictures to WebP? Each is rebuilt at every size and the site starts serving those. The file it replaces is kept unless the WebP screen says otherwise, so this can be undone." => "להמיר %d תמונות ל‑WebP? כל אחת נבנית מחדש בכל הגדלים והאתר מתחיל להגיש אותן. הקובץ שהוחלף נשמר אלא אם מסך ה‑WebP אומר אחרת, כך שאפשר לבטל.",
		"Convert %d pictures to WebP? The site starts serving the new files; the old ones stay unless you asked to clear them." => "להמיר %d תמונות ל‑WebP? האתר יתחיל להגיש את הקבצים החדשים; הישנים נשארים אלא אם ביקשתם למחוק אותם.",
		"Convert all %d in the background" => "המר את כל %d ברקע",
