		"Converting — %1\$d of %2\$d" => "ממיר — %1\$d מתוך %2\$d",
		"Cookie consent" => "הסכמה לעוגיות",
		"Cookie consent — the banner, the categories, the log — lives in %s. Every tag here follows the visitor's choice through Google Consent Mode v2 and the marketing flag." => "הסכמה לעוגיות - הבאנר, הקטגוריות, היומן - נמצאת ב%s. כל תג כאן פועל לפי בחירת המבקר דרך Google Consent Mode v2 ודגל השיווק.",
		"Cookies" => "עוגיות",
		"Copied" => "הועתק ✓",
		"Copies titles, descriptions, robots and social fields — posts and taxonomies — onto our keys. Nothing is deleted from Yoast; run it again whenever, and going back stays possible." => "מעתיק כותרות, תיאורים, רובוטים ושדות שיתוף — פוסטים וטקסונומיות — אל המפתחות שלנו. שום דבר לא נמחק מ-Yoast; אפשר להריץ שוב מתי שרוצים, ואפשר לחזור אחורה.",
		"Copy" => "העתקה",
		"Copy link" => "העתקת קישור",
		"Copy the Client ID and the Client Secret into the fields above, tick \"Show the Google button\", and Save." => "מעתיקים את ה-Client ID וה-Client Secret לשדות למעלה, מדליקים \"הצג את כפתור גוגל\" ושומרים.",
		"Copy the address" => "העתקת הכתובת",
		"Corner rounding" => "עיגול פינות",
		"Corners" => "פינות",
		"Corners show when the panel stops short of the screen edges — mostly when it opens under the link." => "הפינות נראות כשהפאנל לא נוגע בקצוות המסך — בעיקר כשהוא נפתח מתחת לקישור.",
		"Could not prepare the downloaded theme folder." => "לא ניתן היה להכין את תיקיית התבנית שהורדה.",
		"Could not save. Nothing was changed." => "השמירה נכשלה. שום דבר לא השתנה.",
		"Could not save. Try again." => "השמירה נכשלה. נסו שוב.",
		"Count the cart before coupons toward free delivery" => "לספור את העגלה לפני קופונים לצורך משלוח חינם",
		"Counted after everything that is not a digit is dropped, so \"052-123 4567\" is ten digits. 0 on either side means no limit there. Applies to the shopper's phone and to a recipient's phones." => "נספרות אחרי שמורידים כל מה שאינו ספרה, כך ש\"052-123 4567\" הן עשר ספרות. 0 בצד כלשהו = בלי מגבלה שם. חל על הטלפון של המזמין ועל הטלפונים של הנמען.",
		"Counted from the moment the page finishes. Any touch, scroll or key loads it at once and this never runs. Below about 6000 the tag lands back inside the window a speed test measures and the whole thing buys nothing." => "נספר מהרגע שהעמוד מסיים. כל נגיעה, גלילה או הקשה טוענת אותה מיד וההמתנה לא רצה כלל. מתחת ל‑6000 בערך התגית חוזרת לתוך החלון שבדיקת מהירות מודדת, וכל העניין לא שווה כלום.",
		"Counted over the last" => "נספר ב",
		"Country field" => "שדה מדינה",
		"Counts" => "ספירות",
		"Counts visits and pages, aggregated. With Google Consent Mode: nothing is stored without your permission." => "סופר ביקורים ועמודים, באופן מצטבר. עם Google Consent Mode: שום דבר לא נשמר בלי הרשאתך.",
		"Coupon" => "קופון",
		"Coupon %s" => "קופון %s",
		"Coupon code" => "קוד קופון",
		"Coupon discount" => "הנחת קופון",
		"Coupon field" => "שדה קופון",
		"Create a redirect automatically" => "יצירת הפניה אוטומטית",
		"Create a second identifier of type Services ID — its identifier (e.g. com.example.site.web) is the client that goes in the field above. Enable \"Sign in with Apple\", press Configure: choose the App ID as primary, add the site's domain, and as Return URL add exactly:" => "יוצרים מזהה שני מסוג Services ID — המזהה שלו (למשל com.example.site.web) הוא ה-client שנכנס בשדה למעלה. מדליקים \"Sign in with Apple\", לוחצים Configure: בוחרים את ה-App ID כראשי, מוסיפים את הדומיין של האתר, וכ-Return URL מוסיפים בדיוק:",
		"Create account" => "פתיחת חשבון",
		"Create automatic internal links" => "צור קישורים פנימיים אוטומטיים",
		"Create feed" => "צור Feed",
		"Create redirect" => "יצירת הפניה",
