		"Fill the four fields above, tick \"Show the Apple button\", Save — and try it. Note: Apple sends the customer's name only on the very first approval; a customer who removes the site under Settings, Apple ID, Sign-In & Security can approve it afresh." => "ממלאים את ארבעת השדות למעלה, מסמנים \"הצג את כפתור אפל\", שומרים — ומנסים. שימו לב: אפל שולחת את שם הלקוח רק באישור הראשון אי-פעם; לקוח שמסיר את האתר תחת הגדרות ← Apple ID ← כניסה ואבטחה יכול לאשר מחדש.",
		"Fill the frame (crop)" => "ממלאת את המסגרת (חיתוך)",
