		"Find a product" => "חיפוש מוצר",
		"Find a product…" => "חיפוש מוצר…",
		"Find them" => "מצא אותם",
		"Finds a phrase in the text that names somewhere else on the site and links it there. The links are added as the page is drawn, so nothing is written into your content and unticking the box puts everything back as it was." => "מאתר בטקסט ביטוי ששייך למקום אחר באתר ומקשר אליו. הקישורים נוספים בזמן הצגת העמוד — שום דבר לא נכתב לתוך התוכן שלך, וביטול הסימון מחזיר הכול בדיוק כפי שהיה.",
		"Finds pictures and videos nothing points at any more. A file is treated as in use if it hangs off a post, if it is named in content or in a setting, or if its name appears anywhere on the site." => "מוצא תמונות וסרטונים שאף אחד כבר לא מפנה אליהם. קובץ נחשב בשימוש אם הוא תלוי בפוסט, אם הוא נזכר בתוכן או בהגדרה, או אם שמו מופיע במקום כלשהו באתר.",
		"Finds pictures and videos nothing points at any more. A file is treated as in use if it hangs off a post, if its ID appears in any field that holds media, or if its name is written anywhere at all — content, settings or the customizer. Anything in the least doubtful is kept." => "מאתר תמונות וסרטונים שאף אחד כבר לא מפנה אליהם. קובץ נחשב בשימוש אם הוא משויך לפריט כלשהו, אם המזהה שלו מופיע באחד השדות שמחזיקים מדיה, או אם שמו כתוב במקום כלשהו — בתוכן, בהגדרות או במתאים אישית. כל מה שיש לגביו ספק כלשהו — נשמר.",
		"Finish" => "סיום",
		"Finished. %1\$d pictures converted, %2\$s lighter." => "הסתיים. %1\$d תמונות הומרו, %2\$s נחסכו.",
		"First" => "ראשונה",
		"First name" => "שם פרטי",
		"Fit" => "אוטומטי",
		"Fix images embedded in the editor without an ALT" => "תקן תמונות שהוטמעו בעורך בלי ALT",
		"Fixed height" => "קבוע",
		"Fixed target (optional) — overrides the step-up logic" => "יעד קבוע (רשות) — גובר על לוגיקת העלייה ברמה",
		"Flashy fetches its library while the page is still painting, and running it is the heaviest thing on the phone at that moment. With this on, the tag is fetched once the page has finished and the visitor is idle — or the instant they touch anything. Nothing is dropped: the events queue up and are sent as soon as it arrives." => "Flashy מושכת את הספרייה שלה בזמן שהעמוד עדיין מצייר, וההרצה שלה היא הדבר הכבד ביותר בטלפון באותו רגע. כשזה דלוק, התגית נמשכת אחרי שהעמוד סיים והמבקר במנוחה — או ברגע שהוא נוגע במשהו. שום דבר לא הולך לאיבוד: האירועים נערמים בתור ונשלחים ברגע שהיא מגיעה.",
		"Flashy — held back until marketing consent when its deferral is on in Settings → Marketing." => "Flashy - מעוכב עד להסכמה לשיווק כשהדחייה שלו פעילה בהגדרות ← שיווק.",
		"Flip the app from Development to Live (the toggle at the top). The basic email and public_profile permissions need no review." => "מעבירים את האפליקציה מ-Development ל-Live (המתג למעלה). ההרשאות הבסיסיות email ו-public_profile לא דורשות אישור.",
		"Floating — bottom left" => "צף — שמאל למטה",
		"Floating — bottom right" => "צף — ימין למטה",
		"Floor" => "קומה",
