		"For a direct chat with the store." => "לשיחה ישירה עם החנות.",
		"For a typeface the shop has bought. Give it a name, upload the files below, then publish and reopen this panel — the name appears in the two lists above." => "לפונט מסחרי שרכשתם. תנו לו שם, העלו את הקבצים למטה, פרסמו ופתחו מחדש את המקטע — השם יופיע בשתי הרשימות שלמעלה.",
		"For quiet sites" => "לאתרים שקטים",
		"Forget the order for this category? The shop goes back to its usual one." => "לבטל את הסדר הידני של הקטגוריה הזאת? החנות תחזור לסדר הרגיל שלה.",
