		"From another plugin" => "מתוסף אחר",
		"From now on every picture uploaded is written as WebP, at every size. The file you chose is kept beside it, untouched." => "מעכשיו כל תמונה שמעלים נכתבת כ‑WebP, בכל הגדלים. הקובץ שבחרתם נשמר לצידה, ללא שינוי.",
		"From now on, every size WordPress makes from an uploaded picture is written as WebP — a quarter of the weight, same picture. The file you upload keeps its own format, and nothing already on the site changes." => "מעכשיו, כל גודל שוורדפרס מייצר מתמונה שמעלים נכתב כ‑WebP — רבע מהמשקל, אותה תמונה. הקובץ שאתם מעלים נשאר בפורמט שלו, ושום דבר שכבר קיים באתר לא משתנה.",
		"From price to price" => "ממחיר עד מחיר",
