		"Gentle: the picture drifts slower than the page. Full: the picture stands still and the page glides over it." => "עדין — התמונה זזה לאט יותר מהעמוד. מלא — התמונה עומדת במקום והעמוד גולש מעליה.",
		"Gift wrap" => "אריזת מתנה",
		"Give it the address of any page on the site and it reads that page the way a browser does: every picture and film the page names, heaviest first. This is the weight a visitor to that page pays." => "הזינו כתובת של כל עמוד באתר, והכלי יקרא אותו כמו שדפדפן קורא: כל תמונה וסרטון שהעמוד מבקש, מהכבד לקל. זה המשקל שמבקר בעמוד הזה משלם.",
		"Give mobile its own" => "מיקום נפרד למובייל",
		"Give the address on the account and a link to set a new password is on its way." => "הזינו את כתובת המייל של החשבון ויישלח אליכם קישור להגדרת סיסמא חדשה.",
		"Give the product a swatch-type attribute (for example: colour) and its values appear here." => "שייך למוצר תכונה מסוג Swatch (למשל: צבע) והערכים שלה יופיעו כאן.",
		"Global design" => "עיצוב גלובלי",
