		"Google Cloud Console → Credentials → OAuth client (Web). Authorised redirect URI:" => "Google Cloud Console ← Credentials ← OAuth client (Web). כתובת ה-Redirect המאושרת:",
		"Google Consent Mode v2 is always wired; the choice only sets what a visitor starts with." => "Google Consent Mode v2 מחובר תמיד; הבחירה קובעת רק במה מבקר מתחיל.",
