		"Grows from the start of the word" => "צומח מתחילת המילה",
		"Guess-proofed: five wrong tries pause it for a few minutes, and administrator accounts cannot enter here at all — their door stays the private login path." => "מוגן מניחושים: חמש טעויות משהות לכמה דקות, וחשבונות ניהול כלל לא נכנסים מכאן — הדלת שלהם נשארת נתיב הכניסה הפרטי.",
		"Half days, when a parcel sent in the morning often waits. Off by default." => "ימים קצרים, שבהם חבילה שנשלחת בבוקר לרוב ממתינה. כבוי כברירת מחדל.",
