		"How" => "איך",
		"How a chosen value of a swatch attribute (colour, material) shows in the chips row." => "איך ערך נבחר של תכונת דוגמית (צבע, חומר) מוצג בשורת הצ׳יפים.",
		"How a panel arrives" => "איך נפתח החלון",
		"How big (px)" => "גודל (פיקסלים)",
		"How big in the catalogue" => "גודל בקטלוג",
		"How consent starts" => "איך ההסכמה מתחילה",
		"How far they step under the cursor (px)" => "כמה הם זזים בריחוף (פיקסלים)",
		"How filtering looks. The filter groups themselves stay under Theme settings." => "איך הסינון נראה. קבוצות הסינון עצמן נשארות תחת ״הגדרות תבנית״.",
		"How it will look" => "איך זה ייראה",
		"How long a product counts as new (days)" => "כמה זמן מוצר נחשב חדש (ימים)",
		"How long each part of the page was on screen, over all the visits. Red is where people stopped and read; blue is what they glanced at and passed." => "כמה זמן כל חלק בעמוד היה על המסך, בכל הביקורים יחד. אדום הוא המקום שבו עצרו וקראו; כחול הוא מה שראו לרגע והמשיכו.",
		"How many" => "כמה",
		"How many of each" => "כמה מכל סוג",
		"How many of them to keep" => "כמה מהם לשמור",
		"How many sending days it takes, at the least and at the most. 1 to 3, ordered on a Sunday with a Sunday-to-Thursday week, reads \"arrives 2/12–4/12\"; 3 to 7 opens the window on the third day." => "כמה ימי משלוח זה לוקח, לכל הפחות ולכל היותר. 1 עד 3, בהזמנה ביום ראשון ובשבוע ראשון–חמישי, יוצגו כ״יסופק 2/12–4/12״; 3 עד 7 פותח את החלון ביום השלישי.",
		"How many similar products" => "כמה מוצרים דומים להציג",
		"How many to show" => "כמה להציג",
		"How much" => "כמה",
		"How the checkout is laid out. Texts the shop edits day to day stay under Theme settings." => "המבנה של הקופה. טקסטים שהחנות עורכת בשוטף נשארים תחת ״הגדרות תבנית״.",
		"How the checkout is laid out. Which fields are required, the phone rule and the stock hold are under Theme settings → Checkout." => "איך הקופה מסודרת. אילו שדות חובה, כלל הטלפון ושריון המלאי נמצאים בהגדרות תבנית ← קופה.",
		"How the checkout looks — the summary column, the coupon field, the button — is set in %s." => "איך הקופה נראית — עמודת הסיכום, שדה הקופון, הכפתור — נקבע ב%s.",
		"How the heading, the opening words and the closing lines sit. The order details themselves always follow the shop language." => "איך יושבים הכותרת, מילות הפתיחה ושורות הסיום. פרטי ההזמנה עצמם תמיד לפי שפת החנות.",
		"How the order-received page is laid out." => "המבנה של עמוד ״ההזמנה התקבלה״.",
		"How the search panel presents itself. What it searches, and the words it answers to, live under Theme settings." => "איך פאנל החיפוש מוצג. איפה הוא מחפש ולאילו מילים הוא עונה — בהגדרות התבנית.",
		"How this was worked out" => "איך חושב המספר",
		"How to get the keys from Apple — step by step" => "איך מוציאים את המפתחות מאפל — שלב אחר שלב",
		"How to get the keys from Facebook — step by step" => "איך מוציאים את המפתחות מפייסבוק — שלב אחר שלב",
		"How to get the keys from Google — step by step" => "איך מוציאים את המפתחות מגוגל — שלב אחר שלב",
		"How was your purchase experience?" => "איך היתה חוויית הרכישה?",
		"How wide (px)" => "רוחב (פיקסלים)",
		"How wide it opens" => "באיזה רוחב הוא נפתח",
		"I agree to receive updates and offers by email and SMS" => "אני מאשר/ת קבלת עדכונים ומבצעים במייל וב-SMS",
		"I agree to the " => "אני מסכים/ה ל",
		"I have a gift for you — %1\$s%% off your first order here: %2\$s" => "יש לי מתנה בשבילך — %1\$s%% הנחה בהזמנה הראשונה שלך כאן: %2\$s",
		"I have read and accept the privacy policy" => "קראתי ואני מאשר את מדיניות הפרטיות",
		"I'm sending to someone else" => "אני שולח למישהו אחר",
