		"Icon %d text" => "טקסט אייקון %d",
		"Icon size" => "גודל אייקונים",
		"Icon stroke weight" => "עובי קו האייקונים",
		"Icon that opens a bar" => "אייקון שפותח פס חיפוש",
		"Icons" => "אייקונים",
		"Icons under the button" => "אייקונים מתחת לכפתור",
		"Id" => "מזהה",
		"Identifiers, press the plus. Choose App IDs, Continue; on the next screen choose App (not App Clip), Continue. Description: the site name; Bundle ID: Explicit, e.g. com.company.site. The capabilities list is long — use the magnifier to search \"Sign in\", tick Sign in with Apple and nothing else. Continue, Register." => "Identifiers ← לוחצים על הפלוס. בוחרים App IDs ← Continue; במסך הבא בוחרים App (לא App Clip) ← Continue. Description: שם האתר; Bundle ID: Explicit, למשל com.company.site. רשימת היכולות ארוכה — מחפשים עם הזכוכית-מגדלת \"Sign in\", מסמנים Sign in with Apple ותו לא. Continue ← Register.",
		"If that address is on an account, the link is on its way." => "אם הכתובת רשומה אצלנו, הקישור בדרך אליכם.",
		"If these became WebP" => "אם אלה יהפכו ל‑WebP",
