		"Imported %s rules." => "יובאו %s כללים.",
		"In Development mode the login works only for the app's own admins — handy for a first test. Once it works, flip the toggle at the top to Live so every customer can sign in. The basic email and public_profile permissions need no review." => "במצב Development ההתחברות עובדת רק לאדמינים של האפליקציה — נוח לבדיקה ראשונה. כשעובד, מעבירים את המתג למעלה ל-Live כדי שכל לקוח יוכל להיכנס. ההרשאות הבסיסיות email ו-public_profile לא דורשות אישור.",
		"In demand! %d bought recently" => "ביקוש גבוה! %d רכשו לאחרונה",
		"In one row" => "בשורה אחת",
		"In place" => "במקום",
		"In stock" => "במלאי",
		"In stock first" => "מה שבמלאי קודם",
		"In stock only" => "הצג במלאי בלבד",
		"In the InforU system: Account details → API Token." => "במערכת InforU: פרטי חשבון ← API Token.",
		"In the app dashboard open Use cases, press Customize on the login use case, and under Permissions and features make sure email says \"Ready for testing\". Do not add any other permission — extras like birthday drag the app into a full App Review, and the panel only stores a name and an email anyway." => "בלוח האפליקציה נכנסים ל-Use cases, לוחצים Customize על שימוש ההתחברות, ותחת Permissions and features מוודאים ש-email במצב \"Ready for testing\". לא מוסיפים שום הרשאה אחרת — תוספות כמו יום הולדת גוררות App Review מלא, והפאנל ממילא שומר רק שם ומייל.",
		"In the centre, everything centred" => "במרכז, הכול ממורכז",
		"In the middle" => "במרכז",
		"In their words" => "תגובה",
		"In use" => "בשימוש",
		"Include the shipping price" => "לכלול את מחיר המשלוח",
		"Included in free delivery" => "כלולה במשלוח חינם",
		"Including VAT" => "כולל מע\"מ",
