		"Inline search field" => "שדה חיפוש בהדר",
		"Input fields" => "שדות הזנה",
		"Inside a tab" => "בתוך טאב",
		"Inside the app: Facebook Login, Settings — and under \"Valid OAuth Redirect URIs\" add exactly:" => "בתוך האפליקציה: Facebook Login ← Settings — ותחת \"Valid OAuth Redirect URIs\" מוסיפים בדיוק:",
		"Inside the bar, after the groups" => "בתוך הבר, אחרי הסינונים",
		"Inside the bar, beside each group" => "בתוך הבר, ליד כל סינון",
		"Inside the gallery" => "בתוך הגלריה",
		"Internal links" => "קישורים פנימיים",
		"International numbers too" => "גם מספרים בינלאומיים",
		"Invite customers to follow the store" => "הזמנת לקוחות לעקוב אחרי החנות",
		"Invite to join the group" => "הזמנה להצטרף לקבוצה",
		"Israel" => "ישראל",
		"Israeli law requires an informed notice and a real way to refuse; EU law requires a yes before anything runs. \"By region\" gives each visitor what their law asks." => "החוק הישראלי דורש הודעה מיודעת ודרך אמיתית לסרב; החוק האירופי דורש אישור לפני שמשהו פועל. \"לפי אזור\" נותן לכל מבקר את מה שהחוק שלו מבקש.",
		"Israeli mobile numbers only (recommended — blocks SMS-pumping fraud)" => "מספרי נייד ישראליים בלבד (מומלץ — חוסם הונאת SMS pumping)",
		"It can be ordered right now, and it does not usually stay long." => "אפשר להזמין אותו עכשיו, והוא בדרך כלל לא נשאר הרבה זמן.",
		"It could not be added." => "לא ניתן היה להוסיף.",
		"It is back in stock" => "המוצר חזר למלאי",
		"It is back in stock!" => "המוצר חזר למלאי!",
		"It is back — available to order right now." => "המוצר חזר והוא זמין לרכישה עכשיו.",
		"It is packed and waiting for you at the branch.\nCome whenever it suits you — the address and the opening details are below.\nPlease bring the order number with you, and we will have it ready." => "ההזמנה ארוזה ומחכה לך בסניף.\nאפשר להגיע מתי שנוח לך — הכתובת ופרטי הסניף מופיעים למטה.\nכדאי להביא את מספר ההזמנה, ונוציא אותה מוכנה.",
		"It is packed, it has left us, and it is on its way to you.\nIt should reach you between [from] and [to].\nEverything you ordered is listed below, and we are here if anything needs looking at." => "ההזמנה ארוזה, יצאה מאיתנו, והיא בדרך אליך.\nהיא אמורה להגיע אליך בין [from] ל־[to].\nכל מה שהזמנת מופיע למטה, ואנחנו כאן אם משהו דורש בדיקה.",
		"It sells fast, so it is worth hurrying." => "המוצר נמכר מהר ולכן כדאי להזדרז.",
		"It slides in from" => "נפתחת מהצד",
		"Item" => "פריט",
		"Its LCP today (seconds)" => "ה‑LCP שלו היום (שניות)",
		"Its own look" => "עיצוב משלה",
		"Its products" => "המוצרים שלה",
		"Its sub-category only" => "תת-הקטגוריה שלו בלבד",
		"Its views turn into orders at %1\$.1f%% against %2\$.1f%% shop-wide. Moving it up, or making it a large tile, is worth about %3\$s a month." => "הצפיות בו הופכות להזמנות ב‑%1\$.1f%% מול %2\$.1f%% בכל החנות. העלאה שלו למעלה, או הגדלה לאריח גדול, שווה כ‑%3\$s בחודש.",
		"Join our WhatsApp group" => "להצטרפות לקבוצת הוואטסאפ שלנו",
		"Join the club and earn 5% of your order back in points, to spend on your next purchases." => "הצטרפו למועדון וצברו 5% מערך ההזמנה בנקודות שתוכלו לממש בקניות הבאות.",
		"Just a link" => "קישור בלבד",
		"Keep my account" => "השאר את החשבון",
		"Keep out of the index" => "החרג מהאינדוקס",
		"Keep records for (days)" => "שמירת רשומות למשך (ימים)",
		"Keep the journal" => "שמירת היומן",
		"Keep this email — it holds everything about the order in one place." => "שמור את המייל הזה — הוא מרכז את כל פרטי ההזמנה במקום אחד.",
		"Keep this product out of search results" => "אל תציג את המוצר הזה בתוצאות החיפוש",
		"Keeps the shop working: your cart, your sign-in and your choices in this form. Always on." => "מאפשר לחנות לעבוד: הסל, ההתחברות והבחירות שלך בחלון הזה. תמיד פעיל.",
		"Kept for" => "נשמר למשך",
		"Key ID" => "Key ID",
		"Keys are in place." => "המפתחות במקום.",
		"Keys in the left menu, the plus. Name it, tick Sign in with Apple, Configure, pick the App ID from step 2, Save, Continue, Register — then Download. The .p8 file downloads exactly once, keep it somewhere safe. The Key ID (10 characters) shows on that screen, and stays readable any time under Keys — only the file itself is one-time." => "Keys בתפריט השמאלי ← הפלוס. נותנים שם, מסמנים Sign in with Apple ← Configure ← בוחרים את ה-App ID משלב 2 ← Save ← Continue ← Register — ואז Download. קובץ ה-p8. יורד פעם אחת בלבד, לשמור במקום בטוח. ה-Key ID (10 תווים) מוצג באותו מסך, ונשאר קריא תמיד תחת Keys — רק הקובץ עצמו חד-פעמי.",
		"Keys: create a new key, tick \"Sign in with Apple\", configure it to the App ID, and download the .p8 file — Apple hands it out exactly once. Note the Key ID, and paste the file's contents above." => "ב-Keys: יוצרים מפתח חדש, מסמנים \"Sign in with Apple\", מקשרים ל-App ID ומורידים את קובץ ה-p8. — אפל נותנת אותו פעם אחת בלבד. רושמים את ה-Key ID ומדביקים את תוכן הקובץ למעלה.",
		"Kind" => "סוג",
		"LCP %1\$ss → about %2\$ss, worth roughly +%3\$d points." => "LCP %1\$ss ← בערך %2\$ss, שווה בקירוב +%3\$d נקודות.",
		"Label" => "תווית",
