		"Leads to" => "מוביל אל",
		"Least height of a bare row (px)" => "גובה מינימלי לשורה בלי תמונה (פיקסלים)",
		"Leave a comment" => "השאירו תגובה",
		"Leave a field empty to keep the shop-wide pace (wide: %1\$s, large: %2\$s). 0 turns it off for this category alone." => "שדה ריק שומר על הקצב של כל החנות (רחב: %1\$s, גדול: %2\$s). 0 מכבה את הקצב בקטגוריה הזו בלבד.",
		"Leave a field empty to use the built-in text in the site's language (Hebrew on a Hebrew site, English otherwise)." => "השאירו שדה ריק כדי להשתמש בטקסט המובנה בשפת האתר (עברית באתר בעברית, אנגלית אחרת).",
		"Leave arranging" => "יציאה מסידור",
		"Leave empty and the heading is plain text." => "השאירו ריק והכותרת תהיה טקסט בלבד.",
		"Leave empty for no heading." => "השאירו ריק — בלי כותרת.",
		"Leave empty for the automatic height." => "השאירו ריק לגובה אוטומטי.",
		"Leave empty for the whole shop." => "ריק = כל החנות.",
		"Leave empty to keep the saved key. Type \"clear\" to remove it." => "השאירו ריק כדי לשמור על המפתח הקיים. הקלידו clear כדי להסיר אותו.",
		"Leave empty to use the name from the shipping rules." => "ריק — השם מכללי המשלוח.",
		"Leave empty to use the one above." => "ריק = אותה תמונה.",
		"Leave out of similar products" => "להשאיר מחוץ למוצרים דומים",
		"Leave the address empty for the whole library. Fill it in and only the pictures that page uses are listed." => "השאירו את הכתובת ריקה לכל הספרייה. מלאו אותה — ויוצגו רק התמונות שאותו עמוד משתמש בהן.",
		"Leave the address empty to search the whole library. Fill it in and only what that page loads is weighed." => "השאירו את הכתובת ריקה כדי לחפש בכל ספריית המדיה. מלאו אותה — וייבדק רק מה שאותו עמוד טוען.",
		"Leave the address empty to search the whole library. Fill it in and only what that page loads is weighed. Choose \"the average file\" to see just the ones pulling that page down — on one page the average is the page's own, not the library's." => "השאירו את הכתובת ריקה כדי לחפש בכל הספרייה. מלאו אותה ורק מה שהעמוד הזה טוען יישקל. בחרו ב״הקובץ הממוצע״ כדי לראות רק את אלה שמושכים את העמוד למטה — בעמוד בודד הממוצע הוא של העמוד עצמו, לא של הספרייה.",
		"Leave the last one empty. To remove a tag, clear its code and save." => "השאירו את האחרון ריק. כדי להסיר תג, נקו את הקוד שלו ושמרו.",
		"Leave the spare width in front of it" => "השאר את הרווח הפנוי לפניו",
		"Leave the table empty to use the shop-wide layout set in %s." => "טבלה ריקה = הפריסה הכללית של החנות, שנקבעת ב%s.",
		"Leave them out" => "לא להציג בכלל",
		"Leave this empty" => "להשאיר ריק",
		"Left" => "שמאל",
		"Left empty the area sits on the page as it does now. A colour gives it its own band, with room around the products." => "אם נשאר ריק, האזור יישאר על העמוד כפי שהוא היום. צבע ייתן לו רצועה משלו, עם מרווח סביב המוצרים.",
		"Left empty, the branch's own name is used." => "אם השדה ריק, יוצג שם הסניף עצמו.",
		"Left empty, the heading from the Customizer is used." => "אם נשאר ריק, תוצג הכותרת מההתאמה האישית.",
		"Left unbounded a long article turns into a mesh of links and reads as spam. Five is a sensible ceiling." => "בלי הגבלה, כתבה ארוכה הופכת לרשת של קישורים ונקראת כספאם. חמישה הם תקרה הגיונית.",
		"Less" => "פחות",
		"Lets advertising networks show you offers that fit what you looked at here, and measure whether their ads work." => "מאפשר לרשתות פרסום להציג לך הצעות שמתאימות למה שראית כאן, ולמדוד אם המודעות שלהן עובדות.",
