		"Map these directly in the Custom Fields screen. An empty column never deletes a value — it returns the field to automatic. The image ALT imports to the core key _wp_attachment_image_alt." => "ממפים אותם ישירות במסך Custom Fields. עמודה ריקה אף פעם לא מוחקת ערך — היא מחזירה את השדה למצב אוטומטי. ALT לתמונה מיובא למפתח הליבה ‎_wp_attachment_image_alt.",
