		"Necessary" => "הכרחי",
		"Need a hand?" => "צריך עזרה?",
		"Needed once per site, about ten minutes. Three things are created at Apple: an App ID (the primary identity), a Services ID (the site's identity — this is the \"client\"), and a key (.p8 file). The Team ID is not created — it already exists." => "עושים פעם אחת לאתר, בערך עשר דקות. יוצרים אצל אפל שלושה דברים: App ID (הזהות הראשית), Services ID (הזהות של האתר — זה ה\"client\"), ומפתח (קובץ p8.). את ה-Team ID לא יוצרים — הוא כבר קיים.",
		"Negative" => "נגטיב",
