		"Next message" => "המסר הבא",
		"Next, Done — and do not leave without pressing Save at the top; this screen forgets silently." => "Next ← Done — ולא לצאת בלי ללחוץ Save למעלה; המסך הזה שוכח בשקט.",
		"No" => "לא",
		"No account found for this number — continue with the details below." => "לא נמצא חשבון עם המספר הזה — המשך עם הפרטים למטה.",
		"No banner" => "ללא באנר",
		"No banner, no consent layer" => "בלי באנר ובלי שכבת הסכמה",
		"No blocks yet." => "אין בלוקים עדיין.",
		"No blocks yet. This link opens as a plain drop-down if it has children, and as a plain link if it does not." => "אין עדיין בלוקים. הקישור ייפתח כתפריט רגיל אם יש לו תתי־קישורים, ואחרת יהיה קישור פשוט.",
		"No border, centred" => "ללא מסגרת · ממורכז",
		"No border, start-aligned" => "ללא מסגרת · יישור להתחלה",
		"No branches yet. Add one and it is offered at the checkout to anyone choosing collection." => "עדיין אין סניפים. הוסיפו סניף והוא יוצע בקופה לכל מי שבוחר איסוף עצמי.",
		"No brands exist yet on this site." => "עדיין אין מותגים באתר.",
		"No brands yet." => "אין עדיין מותגים.",
		"No category by that name." => "אין קטגוריה בשם הזה.",
		"No darkening" => "ללא",
		"No discount" => "ללא הנחה",
		"No extra scopes and no Google verification are needed — the sign-in only uses the basic name-and-email profile. Every client site gets its own project and its own keys." => "לא צריך להוסיף Scopes ולא נדרש אימות של גוגל — הכניסה משתמשת רק בפרופיל הבסיסי של שם ומייל. כל אתר לקוח מקבל פרויקט משלו ומפתחות משלו.",
		"No feeds yet." => "אין עדיין פידים.",
		"No filters here" => "ללא סינון בקטגוריה זו",
		"No imports yet." => "אין עדיין ייבואים.",
		"No keys yet — Turnstile stays off until both are saved." => "עדיין אין מפתחות – Turnstile כבוי עד ששניהם יישמרו.",
		"No leads yet." => "אין לידים עדיין.",
		"No margin around the picture: it meets the card’s edges, and its top corners follow the card." => "בלי שוליים סביב התמונה: היא מגיעה עד קצוות הכרטיס, והפינות העליונות שלה לפי הכרטיס.",
		"No match found" => "לא נמצאה התאמה",
		"No menu is assigned to the primary location yet. Set one on the %s screen and come back." => "עדיין לא שויך תפריט למיקום הראשי. הגדירו אחד במסך %s וחזרו לכאן.",
		"No movement" => "בלי תנועה",
		"No parallax" => "ללא",
		"No picture, no banner." => "בלי תמונה אין באנר.",
		"No post, no field and no page mentions these. Safe to remove." => "אף פריט, שדה או עמוד לא מזכיר אותן. אפשר למחוק בבטחה.",
		"No presses in this period." => "אין לחיצות בתקופה הזו.",
		"No privacy policy page is set. The banner shows without a link until there is one." => "לא הוגדר עמוד מדיניות פרטיות. הבאנר מוצג בלי קישור עד שיהיה כזה.",
		"No products match this combination — try removing one of the filters." => "אין מוצרים שתואמים את השילוב — אפשר להסיר אחד מהסינונים.",
		"No ratings yet." => "אין דירוגים עדיין.",
		"No ratings yet. Switch the survey on in Thank-you page settings." => "אין דירוגים עדיין. מפעילים את הסקר בהגדרות דף התודה.",
		"No results for \"%s\" — try a different search:" => "לא מצאנו תוצאות עבור ״%s״ — נסו חיפוש אחר:",
		"No rules yet — the form above makes the first one." => "אין עדיין כללים — הטופס למעלה יוצר את הראשון.",
		"No searches recorded in the last 30 days." => "לא נרשמו חיפושים ב־30 הימים האחרונים.",
		"No searches recorded yet." => "עדיין לא נרשמו חיפושים.",
		"No signups yet — they collect from the notify popup on sold-out products." => "אין הרשמות עדיין — הן נאספות מהפופ-אפ במוצרים שאזלו מהמלאי.",
		"No spam — a single update about this product only." => "בלי ספאם — עדכון אחד בלבד, רק על המוצר הזה.",
		"No stock alerts yet — sign up from any sold-out product." => "אין התראות מלאי כרגע — אפשר להירשם מכל מוצר שאזל.",
		"No such product." => "אין מוצר כזה.",
		"No taps in the last 30 days." => "לא היו לחיצות ב־30 הימים האחרונים.",
		"No title" => "בלי כותרת",
		"No user account carries that number." => "אין חשבון משתמש עם המספר הזה.",
		"Nobody is waiting right now." => "אין ממתינים כרגע.",
		"Nofollow" => "Nofollow",
		"Noindex (1/0, yes/no — every spelling accepted)" => "החרגה מאינדוקס (1/0, כן/לא — כל צורת כתיבה מתקבלת)",
		"Noindex by default" => "החרג מאינדוקס כברירת מחדל",
		"None" => "ללא",
		"None of these products are available right now." => "אף אחד מהמוצרים אינו זמין כרגע.",
		"None ticked means all of them." => "בלי סימון — כולם מוצגים.",
		"None — I will list my own" => "ללא — ארשום בעצמי",
		"None — every main photo belongs to a colour." => "אין – כל תמונה ראשית שייכת לצבע.",
		"None — plain title" => "ללא — כותרת רגילה",
		"Normal" => "רגיל",
		"Normal / 2×2" => "רגיל / 2×2",
		"Normal size on a phone" => "גודל רגיל במובייל",
		"Normal — one cell" => "רגיל — תא אחד",
		"Normalised match" => "התאמה מנורמלת",
		"Not allowed." => "אין הרשאה.",
		"Not available" => "לא זמין",
		"Not built yet" => "עדיין לא נבנה",
		"Not registered yet?" => "עדיין לא רשומים?",
		"Not relevant" => "לא רלוונטי",
		"Not yet WebP (JPEG / PNG)" => "עדיין לא WebP (JPEG / PNG)",
		"Note" => "הערה",
		"Note from the customer:" => "הערת הלקוח:",
		"Note under the comment form" => "הערה מתחת לטופס התגובה",
		"Note: a Facebook account registered by phone may carry no email — the customer still gets an account, anchored to their Facebook identity." => "שימו לב: חשבון פייסבוק שנרשם עם טלפון עשוי להיות בלי מייל — הלקוח עדיין מקבל חשבון, מעוגן לזהות הפייסבוק שלו.",
		"Nothing answers to \"%s\". Try another word?" => "לא נמצאו תוצאות עבור ״%s״. אולי מילה אחרת?",
		"Nothing found for “%s”" => "לא נמצאו תוצאות עבור ״%s״",
		"Nothing found." => "לא נמצאו תוצאות.",
		"Nothing here yet." => "אין כאן עדיין כלום.",
		"Nothing here." => "אין כאן כלום.",
		"Nothing in the library is that big." => "אין בספרייה קובץ בגודל כזה.",
		"Nothing is stored for a page nobody visits, so a big shop costs no more than a small one until people actually look — but the list of pages grows with the shop." => "לא נשמר דבר עבור עמוד שאיש לא ביקר בו, כך שחנות גדולה לא עולה יותר מקטנה עד שגולשים באמת מסתכלים — אבל רשימת העמודים גדלה עם החנות.",
		"Nothing is ticked." => "לא סומן דבר.",
		"Nothing needs your attention right now. The rules run again every morning." => "אין כרגע משהו שדורש טיפול. החוקים רצים שוב כל בוקר.",
		"Nothing points at it" => "שום דבר לא מפנה אליו",
		"Nothing recorded for this page, device and period yet." => "עדיין לא נרשם דבר לעמוד, למכשיר ולתקופה האלה.",
		"Nothing recorded in this period yet. A page appears here once people have visited it." => "עדיין לא נרשם דבר בתקופה הזאת. עמוד מופיע כאן אחרי שגולשים ביקרו בו.",
		"Nothing recorded in this period yet. The pages below are the ones being watched; a map appears once people have visited them." => "עדיין לא נרשם דבר בתקופה הזאת. העמודים שלמטה הם אלה שבמעקב, ומפה תופיע אחרי שיבקרו בהם.",
		"Nothing recorded yet." => "עדיין לא נרשם דבר.",
		"Nothing sent yet." => "עדיין לא נשלח דבר.",
		"Nothing sold yet and nothing chosen? The newest products stand in, so the panel is never empty." => "עוד לא נמכר כלום ולא נבחר כלום? המוצרים החדשים ביותר יוצגו במקום, כדי שהפאנל אף פעם לא יהיה ריק.",
		"Nothing to add." => "אין מה להוסיף.",
		"Nothing to clean — every file in the library is spoken for." => "אין מה לנקות — לכל קובץ בספרייה יש מי שמשתמש בו.",
		"Nothing to print — no order was found." => "אין מה להדפיס — לא נמצאה הזמנה.",
		"Nothing to put in order." => "אין מה לסדר.",
		"Nothing was selected." => "לא סומן דבר.",
		"Nothing was sent — add at least one recipient and save first." => "לא נשלח דבר – הוסיפו לפחות נמען אחד ושמרו קודם.",
		"Nothing yet — either the search is answering everyone, or it has not been used much." => "עוד כלום — או שהחיפוש עונה לכולם, או שעדיין לא השתמשו בו הרבה.",
		"Notification channel" => "ערוץ שליחת ההתראות",
		"Notify colour (empty = CTA colour)" => "צבע כפתורי \"עדכנו אותי\" (ריק = צבע CTA)",
		"Notify me" => "עדכנו אותי",
		"Notify me when it is back" => "עדכנו אותי כשהמוצר חוזר",
		"Notify text colour (empty = white)" => "צבע טקסט \"עדכנו אותי\" (ריק = לבן)",
		"Nowhere — hidden" => "בשום מקום — מוסתר",
		"OC Theme needs WooCommerce. Shop features stay hidden until it is active." => "תבנית OC זקוקה ל-WooCommerce. יכולות החנות מוסתרות עד שהתוסף יופעל.",
		"OC shipping" => "משלוח OC",
		"OC shipping is now pricing delivery in the “%1\$s” zone; %2\$d of WooCommerce’s own methods were paused." => "משלוח OC מתמחר עכשיו את המשלוח באזור ״%1\$s״; %2\$d משיטות ווקומרס הושבתו זמנית.",
		"Off" => "כבוי",
		"Off by default — a linked heading looks like a mistake to most readers." => "כבוי כברירת מחדל — כותרת מקושרת נראית לרוב הקוראים כמו טעות.",
		"Off for most stores, and off to begin with. Turn it on and the Branches screen joins the menu, and a shopper who chooses collection at the checkout is asked which branch to collect from." => "ברוב החנויות זה כבוי, וכך גם מלכתחילה. מפעילים — ומסך הסניפים מצטרף לתפריט, ולקוח שבוחר איסוף עצמי בקופה נשאל מאיזה סניף לאסוף.",
		"Off is usually right: a network wants to be told an item is out of stock, and dropping it instead makes the catalogue look like it lost the product." => "בדרך כלל עדיף כבוי: רשת רוצה לדעת שמוצר אזל, והשמטה שלו במקום זה גורמת לקטלוג להיראות כאילו איבד את המוצר.",
		"Off — password only" => "כבוי — סיסמא בלבד",
		"Off — regular category" => "כבוי — קטגוריה רגילה",
		"Off, Google tags load only after a yes (the safest reading of EU law). On, they load at once but store nothing until allowed — Google's recommended setup, which lets it model the conversions it cannot see." => "כבוי - תגי גוגל נטענים רק אחרי אישור (הפרשנות הבטוחה ביותר של החוק האירופי). פעיל - הם נטענים מיד אבל לא שומרים דבר עד שמותר - ההגדרה שגוגל ממליצה עליה, שמאפשרת לה למדל המרות שהיא לא רואה.",
		"Off. WooCommerce prices delivery with its own methods. Switching on pauses those methods in the shop’s zone and prices every parcel by the rules below; switching off gives them back exactly as they were." => "כבוי. ווקומרס מתמחרת את המשלוח בשיטות שלה. הפעלה משביתה זמנית את השיטות האלה באזור של החנות ומתמחרת כל חבילה לפי הכללים כאן; כיבוי מחזיר אותן בדיוק כפי שהיו.",
		"Off: no challenge on any form, nothing to verify. The choices below are kept for when it comes back on. The trap field, the timestamp and the hourly caps stay either way." => "כבוי: אין אימות באף טופס ואין מה לבדוק. הבחירות למטה נשמרות לרגע שיופעל שוב. שדה המלכודת, חותמת הזמן והתקרות לשעה נשארים בכל מקרה.",
		"Off: the chosen variation’s price shows above the button, as WooCommerce does." => "כבוי: מחיר הווריאציה שנבחרה מופיע מעל הכפתור, כמו היום.",
		"Offer a shareable coupon; the referrer earns one back when the friend buys" => "הצעת קופון לשיתוף; המשתף מקבל קופון משלו כשהחבר רוכש",
		"Offer an \"in stock only\" filter" => "הצעת סינון ״במלאי בלבד״",
		"Offer this branch for collection at the checkout" => "לאפשר בחירת הסניף הזה לאיסוף בקופה",
		"Offered on this product's page as one bundle, with this product. The shopper can untick any of them." => "מוצגים בעמוד המוצר כחבילה אחת, יחד עם המוצר הזה. הלקוח יכול להסיר כל אחד מהם.",
		"Often bought together" => "נקנים יחד לעיתים קרובות",
		"Old address" => "כתובת ישנה",
		"Older orders are being summarised in the background, a month at a time." => "הזמנות ישנות מסוכמות ברקע, חודש בכל פעם.",
		"Older orders are being summarised in the background; done back to %s so far." => "הזמנות ישנות מסוכמות ברקע; עד כה הושלם אחורה עד %s.",
		"On" => "פעיל",
		"On Android devices, worth a glance at the spam folder." => "במכשירי אנדרואיד מומלץ לבדוק גם בספאם.",
		"On a Mac: right-click the downloaded AuthKey_XXXX.p8, Open With, TextEdit. Select all, copy, and paste into the Private key field above — with or without the BEGIN/END lines, both work." => "במק: קליק ימני על AuthKey_XXXX.p8 שירד ← Open With ← TextEdit. לבחור הכל, להעתיק ולהדביק בשדה המפתח הפרטי למעלה — עם או בלי שורות ה-BEGIN/END, שתי הצורות עובדות.",
		"On a category item, \"this item's category\" keeps only brands that have products in it." => "בפריט של קטגוריה, ״הקטגוריה של הפריט״ משאיר רק מותגים שיש להם מוצרים בה.",
		"On a desktop" => "בדסקטופ",
		"On a phone" => "במובייל",
		"On each card" => "מה מוצג בכל פוסט",
		"On hold" => "בהמתנה",
		"On hover" => "בריחוף",
		"On its way" => "יצאה אליך",
		"On one page (optional)" => "בעמוד מסוים (לא חובה)",
		"On sale" => "במבצע",
		"On the Overview screen press \"Create OAuth client\": Application type — Web application, any name, and under Authorized redirect URIs add exactly:" => "במסך ה-Overview לוחצים \"Create OAuth client\": סוג אפליקציה — Web application, שם חופשי, ותחת Authorized redirect URIs מוסיפים בדיוק:",
		"On the picture" => "על התמונה",
		"On upload" => "בהעלאה",
		"On, but no network has an ID yet — nothing is sent." => "פועל, אבל לאף רשת אין עדיין מזהה — שום דבר לא נשלח.",
		"On-sale products" => "מוצרים במבצע",
		"On. Every parcel is priced by the rules below; “OC shipping” is the delivery method in the “%s” zone." => "פועל. כל חבילה מתומחרת לפי הכללים כאן; ״משלוח OC״ היא שיטת המשלוח באזור ״%s״.",
		"On. “OC shipping” is the delivery method in the “%s” zone." => "פועל. ״משלוח OC״ היא שיטת המשלוח באזור ״%s״.",
		"Once a day" => "פעם ביום",
		"One across the width" => "מוצר לרוחב",
		"One cell" => "תא אחד",
		"One check under Audience (in the right-side menu): if the status says Testing — press \"Publish app\". In Testing mode only manually-added test users can sign in." => "בדיקה אחת תחת Audience (בתפריט הצד): אם המצב Testing — לוחצים \"Publish app\". במצב Testing רק משתמשי בדיקה שהוספו ידנית יוכלו להתחבר.",
		"One click brings the existing rules over from Redirection or Rank Math, if their tables are still in the database." => "לחיצה אחת מעבירה את הכללים הקיימים מ-Redirection או Rank Math, אם הטבלאות שלהם עדיין במסד הנתונים.",
		"One column — everything under the greeting" => "עמודה אחת — הכל מתחת לברכה",
		"One group per line, separated by commas. Every word in a line finds everything the others find." => "קבוצה אחת בכל שורה, מופרדת בפסיקים. כל מילה בשורה מוצאת את כל מה שהאחרות מוצאות.",
		"One image for this category, used by the categories block, the sub-category strip and the blog. If empty, the hero image is used." => "תמונה אחת לקטגוריה, בשימוש בלוק הקטגוריות, רצועת תתי-הקטגוריות והבלוג. אם ריק, נעשה שימוש בתמונת הבאנר.",
		"One item" => "פריט אחד",
		"One leaves as the next arrives" => "אחד יוצא בזמן שהבא נכנס",
		"One moment…" => "רגע אחד…",
		"One or more addresses, separated by commas." => "כתובת אחת או יותר, מופרדות בפסיקים.",
		"One page" => "עמוד בודד",
		"One per line. 2026-12-25 closes that day once; 12-25 closes it every year. Anything after the date is its name — 08-09 Stocktaking." => "שורה לכל יום. 2026-12-25 סוגר את היום הזה פעם אחת; 12-25 סוגר אותו בכל שנה. מה שנכתב אחרי התאריך הוא השם שלו — 08-09 ספירת מלאי.",
		"One per line: the phrase, a vertical bar, then the address. These win over anything found automatically — use them for the phrases you actually want to rank for." => "אחד בכל שורה: הביטוי, קו אנכי, ואז הכתובת. אלה גוברים על כל מה שנמצא אוטומטית — השתמש בהם לביטויים שאתה באמת רוצה לקדם.",
		"One photo shows alone; two or three sit side by side." => "תמונה אחת מוצגת לבד; שתיים או שלוש זו לצד זו.",
		"One phrase per line." => "ביטוי אחד בכל שורה.",
		"One picture, centred" => "תמונה אחת במרכז",
		"One product and a peek" => "מוצר אחד והצצה",
		"One product at a time" => "מוצר בודד",
		"One row that scrolls sideways instead of wrapping — links, pills or cards alike. Drag on desktop, swipe on touch." => "שורה אחת שנגללת הצידה במקום להישבר לשורות — לינקים, אליפסות או תמונות. גרירה בדסקטופ, החלקה במגע.",
		"One rule per line, written as: the search = product ids. Those products come first, in the order written, and the rest of the ranking follows." => "כלל אחד בכל שורה, בצורה: החיפוש = מזהי מוצרים. המוצרים האלה יופיעו ראשונים, בסדר שנכתב, ואחריהם שאר הדירוג.",
		"One under another" => "אחד מתחת לשני",
		"Online now" => "זמינים עכשיו",
		"Only %d left in stock" => "נותרו %d במלאי",
		"Only JPEG and PNG pictures can be shrunk here." => "אפשר להקטין כאן רק תמונות JPEG ו‑PNG.",
		"Only JPEG and PNG pictures can become WebP." => "רק תמונות JPEG ו‑PNG יכולות להפוך ל‑WebP.",
		"Only after a word has been searched at least" => "רק אחרי שחיפשו מילה לפחות",
		"Only in these categories (empty = everywhere)" => "רק בקטגוריות אלה (ריק = בכל האתר)",
		"Only necessary" => "רק הכרחי",
		"Only products in stock" => "רק מוצרים במלאי",
		"Only tells when there are too few cards to fill the row." => "משפיע רק כשאין מספיק כרטיסים כדי למלא את השורה.",
		"Only the colour changes" => "רק הצבע משתנה",
		"Only the pictures the page fetches straight away are counted towards the seconds. The ones held back until the visitor scrolls still save their data, but not their time." => "רק התמונות שהעמוד מושך מיד נספרות לטובת השניות. אלה שמחכות לגלילה עדיין חוסכות למבקר דאטה, אבל לא זמן.",
		"Only the search box" => "רק תיבת החיפוש",
		"Only the word and the day are kept. Nothing identifies who searched." => "נשמרת רק המילה והיום. שום דבר לא מזהה מי חיפש.",
		"Only these categories" => "רק הקטגוריות האלה",
		"Only visible when the menu sits on a row of its own, apart from the logo." => "נראה רק כשהתפריט יושב בשורה נפרדת מהלוגו.",
		"Only visits that ended in an order: what buyers did on their way to buying." => "רק ביקורים שהסתיימו בהזמנה: מה שקונים עשו בדרך לקנייה.",
		"Only what is needed" => "רק מה שנחוץ",
		"Only with a hero; without one the strip sits above the products. With the text, they follow its alignment." => "רק כשיש באנר; בלעדיו הרצועה יושבת מעל המוצרים. יחד עם הטקסט הן עוקבות אחרי היישור שלו.",
		"Open %s" => "פתיחת %s",
		"Open Certificates, Identifiers & Profiles. The Team ID shows at the top of every page, next to the company name (10 characters) — copy it into the Team ID field above." => "נכנסים ל-Certificates, Identifiers & Profiles. ה-Team ID מוצג בראש כל עמוד, ליד שם החברה (10 תווים) — מעתיקים אותו לשדה Team ID למעלה.",
		"Open an account in a moment and enjoy:" => "יוצרים חשבון בקלות ונהנים מ:",
		"Open by default" => "פתיחה כברירת מחדל",
