		"Products and categories are chosen by how much they were looked at in the last week, and worked out again every hour." => "מוצרים וקטגוריות נבחרים לפי כמה צפו בהם בשבוע האחרון, ומחושבים מחדש כל שעה.",
		"Products and categories are chosen by traffic and worked out again every hour." => "מוצרים וקטגוריות נבחרים לפי התנועה ומחושבים מחדש כל שעה.",
		"Products and pages indexed" => "מוצרים ועמודים באינדקס",
		"Products are matched live by the condition — nothing to assign or maintain, and they keep their real categories (so a \"category\" filter group works here)." => "המוצרים מותאמים בזמן אמת לפי התנאי — אין מה לשייך או לתחזק, והם שומרים על הקטגוריות האמיתיות שלהם (כך שקבוצת סינון \"קטגוריה\" עובדת כאן).",
