		"Rows with a tick box" => "שורות עם תיבת סימון",
		"Rule: a category with at least 1,000 in sales in the previous 30 days whose sales fell by 25% or more. The note reads the category's own visits to tell traffic from conversion." => "החוק: קטגוריה עם לפחות 1,000 במכירות ב‑30 הימים הקודמים, שהמכירות בה ירדו ב‑25% או יותר. ההערה קוראת את הכניסות לקטגוריה כדי להבחין בין תנועה להמרה.",
		"Rule: a pair of products in at least 15 paid orders over 30 days, neither listing the other under \"bought together\". Worth: 10% of the pair's sales, the usual lift of a visible bundle." => "החוק: זוג מוצרים בלפחות 15 הזמנות ששולמו ב‑30 יום, כשאף אחד מהם לא מציג את השני תחת \"נקנים יחד\". השווי: 10% ממכירות הזוג, העלייה המקובלת מחבילה גלויה.",
		"Rule: a search term with no results, typed at least 10 times in the last 7 days, from the theme's own search log." => "החוק: מילת חיפוש בלי תוצאות, שהוקלדה לפחות 10 פעמים ב‑7 הימים האחרונים, מיומן החיפוש של התבנית.",
		"Rule: at least 100 views and 5 orders in 30 days, a view-to-order rate 40% above the shop's, and not among the first 12 products of its category in the shop's default order. Worth: 60% of its current monthly sales, the usual lift from the first rows." => "החוק: לפחות 100 צפיות ו‑5 הזמנות ב‑30 יום, יחס צפייה‑להזמנה גבוה ב‑40% מהחנות, ולא בין 12 המוצרים הראשונים בקטגוריה שלו בסדר ברירת המחדל. השווי: 60% מהמכירות החודשיות הנוכחיות שלו, העלייה המקובלת מהשורות הראשונות.",
		"Rule: at least 100 views in 30 days and an add-to-cart rate under half the shop's. Worth: the adds the shop average would have produced, at the average order value, times the usual 30% that go on to buy." => "החוק: לפחות 100 צפיות ב‑30 יום ויחס הוספה לסל נמוך מחצי מהממוצע בחנות. השווי: ההוספות שממוצע החנות היה מייצר, לפי ממוצע ההזמנה, כפול 30% שממשיכים לקנות.",
		"Rule: at least 40 product views in 30 days, no stock, and optionally people on the back-in-stock list. Worth: the product's sales over the last 90 days, divided by three." => "החוק: לפחות 40 צפיות במוצר ב‑30 יום, בלי מלאי, ואולי גם ממתינים ברשימת החזרה למלאי. השווי: מכירות המוצר ב‑90 הימים האחרונים, חלקי שלוש.",
		"Rule: in a three-hour window with at least 10 checkouts, completion fell more than 15 points below the 30-day average. Worth: the orders that window would usually have produced, at the average order value." => "החוק: בחלון של שלוש שעות עם לפחות 10 כניסות לקופה, ההשלמה ירדה ביותר מ‑15 נקודות מתחת לממוצע של 30 יום. השווי: ההזמנות שהחלון הזה מייצר בדרך כלל, לפי ממוצע ההזמנה.",
		"Rule: paid orders over 90 days, by weekday and hour; the strongest three-hour window." => "החוק: הזמנות ששולמו ב‑90 יום, לפי יום בשבוע ושעה; חלון שלוש השעות החזק ביותר.",
		"Rules" => "כללים",
		"Run a scan on the Media cleanup screen to see what can go." => "מריצים סריקה במסך ניקוי מדיה כדי לראות מה אפשר למחוק.",
		"Run migration" => "הרץ מיגרציה",
		"Running — %1\$d of %2\$d converted, %3\$s lighter so far. You can close this page." => "רץ — %1\$d מתוך %2\$d הומרו, %3\$s נחסכו עד כה. אפשר לסגור את העמוד.",
		"Runs in batches of 50 — for exports and third-party tools that read the library directly." => "רץ במנות של 50 — לייצוא ולכלי צד שלישי שקוראים את הספרייה ישירות.",
