		"Scroll the cards sideways instead of wrapping. On mobile it is a free finger-swipe that runs to the screen edge." => "גלילת הכרטיסים לצדדים במקום ירידת שורה. במובייל זו החלקת אצבע חופשית שנמשכת עד קצה המסך.",
