		"Search for \"Google Auth Platform\" at the top and open it. Press \"Get started\": app name (the shop's name — this is what shoppers see), support email, Audience: External, a contact email, agree and Create." => "מחפשים למעלה \"Google Auth Platform\" ונכנסים. לוחצים \"Get started\": שם האפליקציה (שם החנות — זה מה שהגולשים רואים), מייל תמיכה, Audience: External, מייל ליצירת קשר, אישור ו-Create.",
