		"Text links" => "קישורי טקסט",
		"Text meant for search engines usually goes under the products, where it does not push them down." => "טקסט שמיועד למנועי חיפוש בדרך כלל הולך מתחת למוצרים, שם הוא לא דוחף אותם למטה.",
		"Text only, no background" => "טקסט בלבד, ללא רקע",
