		"Text weight" => "עובי הטקסט",
		"Thank you %s" => "תודה רבה %s",
		"Thank you for your order" => "תודה על ההזמנה",
		"Thank you — you are on the list." => "תודה — נרשמת לרשימה.",
		"Thank you — your order has been received.\nIt is expected to reach you between [from] and [to].\nWe will email you again the moment it leaves us." => "ההזמנה שלך התקבלה, תודה רבה.\nההזמנה צפויה להגיע אליך בין [from] ל‑[to].\nנודיע לך במייל נוסף ברגע שהמשלוח יצא אליך.",
		"Thank you — your order has been received.\nWe are getting it ready, and we will email you the moment it is waiting for you." => "ההזמנה שלך התקבלה, תודה רבה.\nאנחנו מכינים אותה ונעדכן אותך במייל ברגע שהיא תחכה לך.",
		"Thank you!" => "תודה רבה!",
		"Thank you. We sent you an email — please confirm the request from there." => "תודה. שלחנו לך מייל - יש לאשר את הבקשה משם.",
		"Thank-you page" => "דף תודה",
		"Thank-you page ratings" => "חוות דעת מדף התודה",
		"Thanks for the feedback!" => "תודה על הדירוג!",
		"That address is not on this site." => "הכתובת הזו אינה באתר הזה.",
		"That background reaches" => "הרקע הזה נמשך",
		"That code was not right." => "הקוד שהוזן אינו נכון.",
		"That does not look like a valid phone number." => "זה לא נראה כמו מספר טלפון תקין.",
		"That does not look like an Israeli mobile number." => "זה לא נראה כמו מספר נייד ישראלי.",
		"That does not look like an email address." => "זו לא נראית כמו כתובת מייל תקינה.",
		"That is not the code — look again." => "זה לא הקוד — הציצו שוב.",
		"That order could not be found." => "ההזמנה לא נמצאה.",
		"That page names no pictures or films we can weigh." => "העמוד הזה לא מבקש תמונות או סרטונים שאפשר לשקול.",
		"That print link has expired — pick the orders again." => "קישור ההדפסה פג — בחרו את ההזמנות מחדש.",
		"That product needs a choice made first." => "המוצר הזה דורש בחירה קודם.",
		"That was quick — please take a moment and send again." => "זה היה מהיר – רגע, ואז לשלוח שוב.",
		"That window alone holds %s%% of the last 90 days' orders. A campaign or a message that lands an hour before it works harder." => "החלון הזה לבדו מחזיק %s%% מההזמנות של 90 הימים האחרונים. קמפיין או הודעה שמגיעים שעה לפניו עובדים חזק יותר.",
		"The Cross-sells list on the product's own Linked Products tab. WooCommerce only shows these in the cart; this brings them onto the product page." => "רשימת ה-Cross-sells בלשונית ״מוצרים מקושרים״ של המוצר. ווקומרס מציגה אותם רק בסל; ההגדרה הזו מביאה אותם לעמוד המוצר.",
		"The IDs themselves live in %s." => "המזהים עצמם נמצאים ב%s.",
		"The LCP is optional. Copy it from the speed report and the forecast can say what the saved weight is worth in points." => "ה‑LCP הוא רשות. העתיקו אותו מדוח המהירות והתחזית תוכל לומר כמה שווה המשקל שנחסך בנקודות.",
		"The Team ID sits on the Membership page — copy it into the field above." => "ה-Team ID יושב בעמוד ה-Membership — מעתיקים אותו לשדה למעלה.",
		"The Upsells list on the product's Linked Products tab — a better version of what is being looked at." => "רשימת ה-Upsells בלשונית ״מוצרים מקושרים״ של המוצר — גרסה משודרגת של מה שנצפה כרגע.",
		"The account and all your personal details will be deleted for good — there is no way back. Orders and invoices are kept as the law requires." => "החשבון וכל הפרטים האישיים שלך יימחקו לתמיד — אין דרך חזרה. הזמנות וחשבוניות נשמרות כנדרש בחוק.",
		"The account did not open — try again." => "החשבון לא נפתח — נסו שוב.",
		"The air above and below each row." => "האוויר מעל ומתחת לכל שורה.",
		"The alert was removed." => "ההתראה הוסרה.",
		"The attribute type decides which one leads; the other is the fallback." => "סוג התכונה קובע מה מוצג כברירת מחדל; השני משמש כגיבוי.",
		"The average file" => "הקובץ הממוצע",
		"The band behind the summary and payment column on desktop. Empty = the theme default grey." => "הרקע מאחורי עמודת הסיכום והתשלום בדסקטופ. ריק = האפור של ברירת המחדל.",
		"The banner at the top of every category page that has a banner picture. The picture itself is chosen on each category." => "הבאנר בראש כל עמוד קטגוריה שיש לו תמונת באנר. את התמונה עצמה בוחרים בכל קטגוריה.",
		"The banner at the top of every category page. Each category can still choose its own on its edit screen." => "הבאנר בראש כל עמוד קטגוריה. כל קטגוריה עדיין יכולה לבחור מבנה משלה במסך העריכה שלה.",
		"The banner links to %1\$s. Every site form and the checkout link there too." => "הבאנר מקשר ל%1\$s. כל טופס באתר והתשלום מקשרים לשם גם.",
		"The banner picture" => "תמונת הבאנר",
		"The bar is currently switched off, so these messages are not showing." => "הבר כבוי כרגע, ולכן ההודעות האלה לא מוצגות.",
		"The basics" => "הבסיס",
		"The batch was taken out." => "האצווה הוצאה.",
		"The best sellers" => "הנמכרים ביותר",
		"The biggest drop is %s. That is the step to work on first." => "הנשירה הגדולה ביותר היא %s. זה השלב שכדאי לטפל בו קודם.",
		"The block is switched off right now — turn it on under Customize → Product page → Contact." => "הכרטיס כבוי כרגע. מפעילים אותו בהתאמה אישית ← דף מוצר ← יצירת קשר.",
		"The brands page" => "עמוד המותגים",
		"The built-in tabs. Tab titles and the custom tabs stay under Theme settings." => "הטאבים המובנים. כותרות הטאבים והטאבים המותאמים נשארים תחת ״הגדרות תבנית״.",
		"The button" => "הכפתור",
		"The button opens" => "הכפתור פותח",
		"The button reads “Add to cart · ₪120” and follows the quantity and the chosen variation." => "הכפתור יציג „הוספה לסל · ₪120” ויתעדכן לפי הכמות והווריאציה שנבחרה.",
		"The card’s own corners follow Global design › Corner rounding." => "הפינות של הכרטיס עצמו נקבעות בעיצוב גלובלי › עיגול פינות.",
		"The cart is the same icon the header wears." => "הסל הוא אותו אייקון שנבחר להדר.",
		"The cart items' own upsells" => "המוצרים המוצעים שהוגדרו למוצרים שבסל",
		"The catalogue's own cards, so the add button follows the card setting." => "כרטיסי הקטלוג הרגילים, כך שכפתור ההוספה נגזר מהגדרת הכרטיס.",
		"The category" => "הקטגוריה",
		"The category shown in its path" => "הקטגוריה שמופיעה בנתיב שלו",
		"The classic door — email and password, with a forgot-password link" => "הדלת הקלאסית — מייל וסיסמא, עם קישור לשחזור סיסמא",
		"The code" => "הקוד",
		"The code expired — ask for a new one." => "תוקף הקוד פג — בקשו קוד חדש.",
		"The code is in your inbox." => "הקוד אצלכם במייל.",
		"The codes go out through the service chosen here; only its own fields are asked for below." => "הקודים נשלחים דרך השירות שנבחר כאן; רק השדות שלו יוצגו למטה.",
		"The colours of these products have pictures of their own — a colour gallery or a variation image — and the main photo is none of them. Their catalogue card marks no colour and the product page opens with nothing chosen, so the photo never contradicts the swatch. To have a colour marked again, make the main photo one of that colour's pictures: add it to the colour's gallery (Product data → Colour galleries), set it as that variation's image, or make one of the colour's pictures the main photo." => "לצבעים של המוצרים האלה יש תמונות משלהם – גלריית צבע או תמונת וריאציה – והתמונה הראשית אינה אחת מהן. הכרטיס בקטלוג לא מסמן צבע ודף המוצר נפתח בלי צבע נבחר, כך שהתמונה לעולם לא סותרת את הסוואטש. כדי שיסומן צבע שוב, הפכו את התמונה הראשית לאחת מתמונות אותו צבע: הוסיפו אותה לגלריית הצבע (נתוני מוצר ← גלריות צבע), הגדירו אותה כתמונת הווריאציה, או הפכו אחת מתמונות הצבע לתמונה הראשית.",
		"The columns come from this link's own sub-items, on the screen behind. Add a picture here and they will sit beside it." => "העמודות מגיעות מתתי־הפריטים של הקישור הזה, במסך שמאחור. הוסיפו כאן תמונה והן ישבו לצדה.",
		"The confirmation and order details were sent by email." => "האישור ופרטי ההזמנה נשלחו במייל.",
		"The connection stumbled — try again." => "החיבור נתקע — נסו שוב.",
		"The contact card is not switched on." => "כרטיס יצירת הקשר במוצר לא מופעל.",
		"The content width comes from the site's own; on a wide layout it can look the same as the whole page." => "רוחב התוכן נלקח מרוחב התוכן של האתר; בפריסה רחבה הוא עשוי להיראות זהה לכל רוחב העמוד.",
		"The cost is a visitor who opens the page and leaves before the wait is out without touching it — their page view is never sent." => "המחיר הוא מבקר שפותח את העמוד ועוזב לפני שההמתנה נגמרה בלי לגעת בו — צפיית העמוד שלו לא נשלחת כלל.",
		"The cost is a visitor who opens the page and leaves within a couple of seconds without touching it — their page view may never be sent." => "המחיר הוא מבקר שפותח את העמוד ועוזב תוך שניות ספורות בלי לגעת בו — צפיית העמוד שלו עלולה לא להישלח כלל.",
		"The customer account was deleted at the customer's request; the order is kept as the law requires." => "חשבון הלקוח נמחק לבקשתו; ההזמנה נשמרת כנדרש בחוק.",
		"The daily report goes out in the morning about the whole of yesterday, with the orders themselves; the weekly report goes out on Sunday morning about the week that ended. Both compare to the period before." => "הדוח היומי יוצא בבוקר על כל יום אתמול, כולל ההזמנות עצמן; הדוח השבועי יוצא ביום ראשון בבוקר על השבוע שהסתיים. שניהם מושווים לתקופה שלפניהם.",
		"The details themselves come from Theme settings → Store details. Anything left empty there simply does not appear." => "הפרטים עצמם מגיעים מהגדרות תבנית ← פרטי החנות. מה שריק שם פשוט לא מוצג.",
		"The details you provide will be used to process and deliver your order, for billing and customer service, in line with our %s. Providing them is not required by law, but without them the order cannot be completed." => "הפרטים שמסרת ישמשו לטיפול בהזמנה ולאספקתה, לחיוב ולשירות לקוחות, בהתאם ל%s. מסירת המידע אינה חובה על פי חוק, אך בלעדיה לא ניתן להשלים את ההזמנה.",
		"The drawer" => "המגירה",
		"The drawer — inside a category" => "המגירה — בתוך קטגוריה",
		"The drawer — one level in" => "המגירה — רמה אחת פנימה",
		"The drawer — phone and hamburger" => "המגירה — נייד והמבורגר",
		"The drawer's shape. Titles, free-shipping threshold and upsell rules stay under Theme settings." => "המבנה של המגירה. כותרות, סף המשלוח חינם וכללי ההמלצות נשארים תחת ״הגדרות תבנית״.",
		"The drawers that slide in over the page." => "המגירות שנפתחות מעל העמוד.",
		"The email or the password is wrong." => "המייל או הסיסמא שגויים.",
		"The fields are always shown; this is only whether they may be left empty. Collecting from a branch never requires them." => "השדות תמיד מוצגים; כאן נקבע רק אם מותר להשאיר אותם ריקים. באיסוף מסניף הם אף פעם לא חובה.",
		"The file came up empty." => "הקובץ יצא ריק.",
		"The file is not on the server." => "הקובץ לא נמצא בשרת.",
		"The file it replaced is gone, so this cannot be undone." => "הקובץ שהוחלף נמחק, ולכן אי אפשר לבטל.",
		"The first scan runs by itself within the hour, in the background." => "הסריקה הראשונה תרוץ לבד תוך שעה, ברקע.",
		"The five insights that matter, refreshed every morning" => "חמש התובנות המשמעותיות, מתעדכנות כל בוקר",
		"The floating video loops quietly over the main image; a click opens it full screen." => "הווידאו הצף רץ בלופ שקט מעל התמונה הראשית; לחיצה פותחת אותו על כל המסך.",
		"The footer has three floors. (1) Content columns: three widget areas — Appearance → Widgets → \"Footer column 1/2/3\"; a text widget, a menu widget, contact details, anything. An empty column simply does not render. (2) The bottom bar: the menu assigned to the \"Footer menu\" location (Appearance → Menus) beside the credit line below. (3) This screen styles it all: background, layout, credit. Order of columns follows the site language direction." => "לפוטר שלוש קומות. (1) עמודות תוכן: שלושה אזורי ווידג'טים — עיצוב ← ווידג'טים ← \"עמודת פוטר 1/2/3\"; ווידג'ט טקסט, תפריט, פרטי קשר — כל דבר. עמודה ריקה פשוט לא מוצגת. (2) הפס התחתון: התפריט שמשויך למיקום \"תפריט פוטר\" (עיצוב ← תפריטים) לצד שורת הקרדיט שלמטה. (3) המסך הזה מעצב את הכל: רקע, פריסה, קרדיט. סדר העמודות עוקב אחרי כיוון שפת האתר.",
		"The friend you shared your code with has placed an order. As promised, a coupon of your own:" => "החבר ששיתפת איתו את הקוד ביצע הזמנה. כמו שהבטחנו — קופון משלך:",
		"The gift is for a new customer — it will not apply to your own next order." => "המתנה מיועדת ללקוח חדש — היא לא תחול על ההזמנה הבאה שלך.",
		"The heading links to" => "הכותרת מקשרת אל",
		"The highest one is charged" => "הגבוה מביניהם נגבה",
		"The index is up to date." => "האינדקס מעודכן.",
		"The journal was cleared." => "היומן נוקה.",
		"The key." => "המפתח.",
		"The keys sit at the top of that same Basic screen: App ID is visible, App Secret shows after pressing Show (Facebook asks for your password). Paste both into the fields above." => "המפתחות יושבים בראש אותו מסך Basic: ה-App ID גלוי, וה-App Secret נחשף בלחיצה על Show (פייסבוק תבקש את הסיסמא שלך). מדביקים את שניהם בשדות למעלה.",
		"The last calls the server made to Meta, TikTok and GA4, and what they answered. “Send a test event” fires a PageView through the server with the saved keys." => "הקריאות האחרונות שהשרת עשה למטא, טיקטוק ו‑GA4, ומה הן ענו. ״שליחת אירוע בדיקה״ יורה PageView דרך השרת עם המפתחות השמורים.",
		"The last calls the server made to Meta, TikTok, ChatGPT ads and GA4, and what they answered. “Send a test event” fires a PageView through the server with the saved keys." => "הקריאות האחרונות שהשרת ביצע ל‑Meta, TikTok, פרסום ב‑ChatGPT ו‑GA4, ומה הן ענו. ״שלח אירוע בדיקה״ שולח PageView דרך השרת עם המפתחות השמורים.",
		"The law asks that withdrawing consent is as easy as giving it." => "החוק דורש שביטול ההסכמה יהיה קל כמו מתן ההסכמה.",
		"The left" => "שמאל",
		"The lines that rotate above the header. Leave a slot empty to skip it." => "השורות שמתחלפות מעל ההדר. שדה ריק פשוט מדולג.",
		"The links themselves come from the Menus screen. Whether the desktop shows an open menu or a hamburger is the header layout, above." => "הקישורים עצמם מגיעים ממסך התפריטים. האם בדסקטופ מוצג תפריט פתוח או המבורגר — זו פריסת ההדר, למעלה.",
		"The list grows downwards" => "הרשימה נפתחת כלפי מטה",
		"The list of watched pages was last worked out at %s." => "רשימת העמודים במעקב חושבה לאחרונה ב־%s.",
		"The listing a shopper browses: the grid, the card, and everything drawn on it." => "הרשימה שהלקוח גולש בה: הרשת, הכרטיס, וכל מה שמצויר עליו.",
		"The log is empty." => "היומן ריק.",
		"The login SMS budget (%d a day) ran out — sending is paused until midnight. If this is real traffic, raise the cap under Settings, Login." => "תקציב ה-SMS לכניסה (%d ביום) נגמר — השליחה מושהית עד חצות. אם זו תנועה אמיתית, העלו את התקרה בהגדרות ← התחברות.",
		"The logo comes from Site Identity; menus from the Menus screen." => "הלוגו מוגדר בזהות האתר; התפריטים במסך התפריטים.",
		"The logo is the brand’s own image. A brand without one shows its name." => "הלוגו הוא התמונה של המותג עצמו. מותג בלי תמונה יוצג בשמו.",
		"The mapping expired — upload again." => "המיפוי פג — העלו שוב.",
		"The media scan is running in the background; the tile updates when it finishes." => "סריקת המדיה רצה ברקע; הקוביה תתעדכן כשהיא תסתיים.",
		"The mega panel — desktop" => "המגה־תפריט — דסקטופ",
		"The menu bar" => "שורת התפריט",
		"The message did not go out — try again in a moment." => "ההודעה לא יצאה — נסו שוב בעוד רגע.",
		"The most it will show. A category with fewer products in it shows what it has." => "המקסימום שיוצג. קטגוריה עם פחות מוצרים תציג את מה שיש בה.",
		"The most useful list on this screen. Every line is a shopper who wanted something and left with an empty panel — and almost every one of them is a missing synonym." => "הרשימה הכי שימושית במסך הזה. כל שורה היא גולש שרצה משהו ויצא עם פאנל ריק — וכמעט כל אחת מהן היא מילה נרדפת חסרה.",
		"The most visited categories" => "הקטגוריות הנצפות ביותר",
		"The most visited products" => "המוצרים הנצפים ביותר",
		"The number beside each field is what a match there is worth. A word found in the product name outranks the same word found in a description." => "המספר ליד כל שדה הוא כמה שווה התאמה בו. מילה שנמצאה בשם המוצר גוברת על אותה מילה בתיאור.",
		"The number on your user account — the code arrives by SMS." => "המספר שרשום בחשבון המשתמש שלך — הקוד יגיע ב‑SMS.",
		"The number your account is registered under." => "המספר המשויך לחשבון שלך",
		"The old name is written somewhere on the site, so the old file was kept." => "השם הישן כתוב במקום כלשהו באתר, ולכן הקובץ הישן נשמר.",
		"The ones I choose" => "אלה שאני בוחר",
		"The orders" => "ההזמנות",
		"The original could not be copied aside, so nothing was changed." => "לא ניתן היה לשמור עותק של המקור, ולכן שום דבר לא שונה.",
		"The original could not be put back." => "לא ניתן היה להחזיר את המקור.",
		"The original is kept, so this can always be undone." => "המקור נשמר, כך שתמיד אפשר לבטל.",
		"The page" => "העמוד",
		"The page could not be written." => "לא ניתן היה לכתוב את העמוד.",
		"The page itself, the information tabs, and the other products it shows." => "העמוד עצמו, לשוניות המידע, והמוצרים האחרים שהוא מציג.",
		"The page layout, the contact strip and the order summary are set in %s." => "מבנה העמוד, שורת ערוצי הקשר וסיכום ההזמנה — נקבעים ב%s.",
		"The page of one brand: its products, with its logo, its description and, when it has one, its banner. The pictures are chosen on each brand." => "העמוד של מותג אחד: המוצרים שלו, עם הלוגו, התיאור, וכשיש — הבאנר. התמונות נבחרות בכל מותג.",
		"The page returned nothing." => "העמוד לא החזיר תוכן.",
		"The page went stale — refresh and try again." => "העמוד התיישן — רעננו ונסו שוב.",
		"The page went stale — refresh it and try again." => "העמוד התיישן – רעננו ונסו שוב.",
		"The page you asked for is not here. Try a search instead." => "העמוד המבוקש לא נמצא. אפשר לנסות חיפוש במקום.",
		"The panel a catalogue card opens for a product with options. On a phone it rises from the bottom." => "הפאנל שכרטיס בקטלוג פותח למוצר עם וריאציות. במובייל הוא עולה מלמטה.",
		"The panel shows the last %d days; this screen shows the last 30." => "הפאנל מציג את %d הימים האחרונים; המסך הזה מציג את 30 האחרונים.",
		"The panel that opens" => "הפאנל שנפתח",
		"The paragraph under the heading. Each line is its own paragraph. [from] and [to] become the estimated arrival dates — delete that line to leave the estimate out." => "הפסקה שמתחת לכותרת. כל שורה היא פסקה נפרדת. [from] ו‑[to] מוחלפים בתאריכי ההגעה המשוערים — מחיקת השורה הזאת מסתירה את ההערכה.",
		"The paragraph under the heading. Each line is its own paragraph. [shop] and [name] become the shop name and the person's name." => "הפסקה שמתחת לכותרת. כל שורה היא פסקה בפני עצמה. [shop] ו־[name] מוחלפים בשם החנות ובשם הלקוח.",
		"The paragraph under the heading. One line per paragraph." => "הפסקה שמתחת לכותרת. כל שורה היא פסקה.",
		"The picture" => "התמונה",
		"The picture's focal point (%)" => "מוקד התמונה (%)",
		"The pictures beside the links" => "התמונות לצד הקישורים",
		"The pieces arrive" => "החלקים נכנסים",
		"The places people press" => "המקומות שלוחצים בהם",
		"The plus again, this time choose Services IDs, Continue. Description: anything; Identifier: the App ID's identifier with a suffix, e.g. com.company.site.web — it must differ from the App ID, the two share one namespace. This identifier is the value for the \"Services ID (client)\" field above. Continue, Register." => "שוב הפלוס, הפעם בוחרים Services IDs ← Continue. Description: מה שרוצים; Identifier: המזהה של ה-App ID עם סיומת, למשל com.company.site.web — הוא חייב להיות שונה מה-App ID, השניים חולקים מרחב שמות אחד. המזהה הזה הוא הערך לשדה \"Services ID (client)\" למעלה. Continue ← Register.",
		"The policy page is written and set as the site's privacy page. Read it once before launch." => "עמוד המדיניות נכתב והוגדר כעמוד הפרטיות של האתר. קראו אותו פעם אחת לפני העלייה לאוויר.",
		"The preview expired — upload again." => "התצוגה המקדימה פגה — העלו שוב.",
		"The price at the top follows the chosen variation" => "המחיר העליון מתחלף לפי הווריאציה שנבחרה",
		"The privacy policy needs your approval." => "צריך לאשר את מדיניות הפרטיות.",
		"The product page opens with no colour or size selected, and catalogue cards mark no colour. Unticked, a product without default form values opens on the colour of its main photo." => "דף המוצר נפתח בלי צבע או מידה מסומנים, והכרטיס בקטלוג לא מסמן צבע. בלי הסימון, מוצר שלא הוגדרו לו ערכי ברירת מחדל נפתח על הצבע של התמונה הראשית.",
		"The product you asked to follow is available again. Quantities may be limited — first come, first served." => "המוצר שביקשתם לעקוב אחריו זמין שוב. הכמויות עשויות להיות מוגבלות — כל הקודם זוכה.",
		"The products" => "המוצרים",
		"The products, in the order you want them" => "המוצרים, בסדר שתרצו",
		"The regular variables work here, plus %%filename%% and %%index%%." => "המשתנים הרגילים עובדים כאן, בתוספת %%filename%% ו-%%index%%.",
		"The right" => "ימין",
		"The rule also fires while the word is still being typed, so a shopper sees the pin from the third letter on." => "הכלל פועל גם בזמן שהמילה עדיין מוקלדת, כך שהגולש רואה את הקידום כבר מהאות השלישית.",
		"The rule for every brand; a brand can choose for itself on its own screen. Long text folds to two lines with \"Read more\" either way." => "הכלל לכל המותגים; מותג יכול לבחור לעצמו במסך שלו. טקסט ארוך מתקפל לשתי שורות עם \"קרא עוד\" בכל מקרה.",
		"The rule for every category; a category can choose for itself on its own screen. Brand pages have their own rule under Brand page." => "הכלל לכל הקטגוריות; קטגוריה יכולה לבחור לעצמה במסך שלה. לעמודי מותג יש כלל משלהם תחת עמוד מותג.",
		"The same product in other colours. Links sync both ways: connect black and grey here and each of them links back automatically." => "אותו מוצר בצבעים אחרים. הקישור מסתנכרן לשני הכיוונים: קשרו כאן שחור ואפור — וכל אחד מהם יקושר חזרה אוטומטית.",
		"The same, for an order being collected rather than delivered." => "אותו הדבר, להזמנה שנאספת במקום נשלחת.",
		"The same, for an order being collected. Left empty, the delivery wording is used." => "אותו הדבר להזמנה שנאספת. אם ריק, יוצג הנוסח של המשלוח.",
		"The scan expired. Please run it again." => "הסריקה פגה. יש להריץ אותה שוב.",
		"The shopper's own hold" => "השריון של הלקוח עצמו",
		"The site width, like the content" => "לרוחב האתר, כמו התוכן",
		"The stock line takes turns between what the stock is doing and when the parcel would arrive. Counting starts tomorrow and skips the days you do not send." => "שורת המלאי מתחלפת בין מצב המלאי לבין מועד ההגעה המשוער. הספירה מתחילה ממחר ומדלגת על הימים שבהם אינכם שולחים.",
		"The store's own channels, entered once. Every page that shows them reads from here — the checkout help line, the thank-you page, and any text where you write {phone}, {email} or {whatsapp}. An empty field simply does not appear." => "ערוצי הקשר של החנות, במקום אחד. כל עמוד שמציג אותם מושך מכאן — שורת העזרה בקופה, דף התודה, וכל טקסט שכתוב בו ‎{phone}‎, ‎{email}‎ או ‎{whatsapp}‎. שדה ריק פשוט לא מוצג.",
		"The strip above the header, the header itself, and the menu that drops out of it." => "הרצועה שמעל ההדר, ההדר עצמו, והתפריט שנפתח ממנו.",
		"The test email could not be sent." => "לא ניתן היה לשלוח את מייל הבדיקה.",
		"The test report was sent." => "דוח הבדיקה נשלח.",
		"The theme prices delivery" => "התבנית מתמחרת את המשלוח",
		"The waiting list" => "רשימת הממתינים",
		"The weight is measured. The seconds and the points are a forecast for one metric on a simulated phone — treat them as the direction, not the number." => "המשקל נמדד. השניות והנקודות הן תחזית למדד אחד בטלפון מדומה — יש להתייחס אליהן ככיוון, לא כמספר.",
		"The whole category" => "כל הקטגוריה",
		"The whole page" => "כל רוחב העמוד",
		"The whole picture" => "התמונה במלואה",
		"The whole screen, edge to edge" => "לכל רוחב המסך, מקצה לקצה",
		"The whole shop" => "כל החנות",
		"The width of the content" => "רוחב התוכן",
		"The word lifts" => "המילה מתרוממת",
		"The words" => "הטקסט",
		"The words are" => "הטקסט",
		"The words beside the dot (empty = \"Online now\")" => "הטקסט ליד הנקודה (ריק = ״זמינים עכשיו״)",
		"The words sit" => "מיקום הטקסט",
		"Their corners" => "הפינות שלהן",
		"Their logo" => "הלוגו שלהם",
