		"There is nothing to go back to for this one." => "אין למה לחזור עבור התמונה הזו.",
		"These products have colour galleries, but their main photo sits in none of them. Their catalogue card marks no colour and the product page opens with nothing chosen, so the photo never contradicts the swatch. To have a colour marked again, add the main photo to that colour's gallery (Product data → Colour galleries), or make one of the gallery pictures the main photo." => "למוצרים האלה יש גלריות צבע, אבל התמונה הראשית שלהם לא נמצאת באף אחת מהן. הכרטיס בקטלוג לא מסמן צבע ודף המוצר נפתח בלי צבע נבחר, כך שהתמונה לעולם לא סותרת את הסוואטש. כדי שיסומן צבע שוב, הוסיפו את התמונה הראשית לגלריה של אותו צבע (נתוני מוצר ← גלריות צבע), או הפכו אחת מתמונות הגלריה לתמונה הראשית.",
		"These results, from that brand" => "התוצאות האלה, מהמותג הזה",
		"These results, in that category" => "התוצאות האלה, בקטגוריה הזו",
