		"Those links under the cursor" => "אותם קישורים בריחוף",
		"Thousands of pictures is hours of work. Start it here and it carries on by itself — close the tab, come back whenever. Whatever is converted before you stop stays converted." => "אלפי תמונות הן שעות עבודה. התחילו כאן והמרה תימשך מעצמה — אפשר לסגור את הלשונית ולחזור מתי שרוצים. כל מה שהומר עד שתעצרו נשאר מומר.",
		"Three quick presses on the same spot. Someone pressed, nothing happened, and they pressed again and again: a control that does not answer, or something that only looks like one." => "שלוש לחיצות מהירות באותו מקום. מישהו לחץ, שום דבר לא קרה, והוא לחץ שוב ושוב: כפתור שלא מגיב, או משהו שרק נראה כמו כפתור.",
