		"Turn this off in a shop with no branches and the screen steps out of the menu. Nothing is deleted: the branch pages that exist keep working, and the branches block stays available — it is just as useful for \"where to find our products\"." => "בחנות בלי סניפים אפשר לכבות, והמסך יוצא מהתפריט. שום דבר לא נמחק: עמודי הסניפים הקיימים ממשיכים לעבוד, והבלוק של הסניפים נשאר זמין — הוא מתאים בדיוק באותה מידה ל״איפה אפשר למצוא את המוצרים שלנו״.",
		"Turning it off hides the screen and the question — it deletes nothing. The branches you have keep their pages, and the branches block goes on working, which makes it just as useful for \"where to find our products\"." => "כיבוי מסתיר את המסך ואת השאלה — הוא לא מוחק כלום. הסניפים הקיימים שומרים על העמודים שלהם, והבלוק של הסניפים ממשיך לעבוד — מה שהופך אותו מתאים בדיוק באותה מידה ל״איפה אפשר למצוא את המוצרים שלנו״.",
