		"Upload and preview" => "העלאה ותצוגה מקדימה",
		"Upload only the old site's addresses — a CSV/XLSX with a URL column (extra columns like name, SKU and type sharpen the match), a sitemap.xml, or a pasted list. Every address walks the matching ladder and comes back with a proposed target and a confidence level. Nothing is written before your approval." => "מעלים רק את כתובות האתר הישן — CSV/XLSX עם עמודת כתובת (עמודות נוספות כמו שם, מק\"ט וסוג מחדדות את ההתאמה), sitemap.xml או רשימה מודבקת. כל כתובת עוברת את סולם ההתאמה וחוזרת עם יעד מוצע ורמת ביטחון. שום דבר לא נכתב לפני האישור שלכם.",
		"Uploaded font — bold" => "פונט שהועלה — מודגש",
