		"Upsells in the panel" => "מוצרים מוצעים בפאנל",
		"Use as my default address" => "השתמש בכתובת זו כברירת מחדל",
		"Used instead of the heading above when the order is being collected rather than delivered." => "מוצגת במקום הכותרת שלמעלה כשההזמנה נאספת ולא נשלחת.",
		"Used on phones. If empty, the desktop image is used." => "לשימוש בטלפון. אם ריק, נעשה שימוש בתמונת הדסקטופ.",
