		"Visits" => "כניסות",
		"Visits are counted from the day the statistics were switched on; earlier days show orders only." => "כניסות נספרות מהיום שבו הופעלה הסטטיסטיקה; ימים מוקדמים יותר מציגים הזמנות בלבד.",
		"Visits have been counted since %s; orders before that date are counted, their visits are not — so the funnel and the rates are only complete from that date on." => "הכניסות נספרות מ־%s. הזמנות מלפני התאריך הזה נספרות, אבל הכניסות שלהן לא, ולכן המשפך ויחסי ההמרה מלאים רק מהתאריך הזה והלאה.",
		"Visits that bought" => "ביקורים שקנו",
		"Visits to the category fell too — fewer people reach it. Worth a place on the home page or in the menu." => "גם הכניסות לקטגוריה ירדו – פחות אנשים מגיעים אליה. שווה מקום בדף הבית או בתפריט.",
		"Visits to the category held; the drop is inside it — stock that ran out, a price that changed, or a lead product that fell off the first row." => "הכניסות לקטגוריה נשמרו; הירידה היא בתוכה – מלאי שאזל, מחיר שהשתנה, או מוצר מוביל שירד מהשורה הראשונה.",
		"WP All Import keys" => "מפתחות WP All Import",
		"Wait before loading it anyway (milliseconds)" => "המתנה לפני טעינה בכל מקרה (מילישניות)",
		"Waiting" => "ממתינים",
		"Want to follow us?" => "רוצה לעקוב אחרינו?",
		"Warranty" => "אחריות",
		"We are here — whichever way suits you." => "אנחנו כאן, בכל דרך שנוחה לך.",
		"We could not file that request. Check the address and try again, or write to us directly." => "לא הצלחנו לרשום את הבקשה. בדקו את הכתובת ונסו שוב, או כתבו לנו ישירות.",
		"We could not find \"%1\$s\" — showing results for \"%2\$s\"." => "לא מצאנו את ״%1\$s״ — מציגים תוצאות עבור ״%2\$s״.",
		"We do not know this number yet — fill in your details once, and next time the phone alone gets you in." => "המספר עדיין לא מוכר לנו — מלאו פרטים פעם אחת, ובפעם הבאה נכנסים עם הטלפון בלבד.",
		"We have received your order and we are already getting it ready.\nIt is expected to reach you between [from] and [to].\nWe will email you again the moment it leaves us, so you know exactly where it is." => "קיבלנו את ההזמנה שלך ואנחנו כבר מכינים אותה.\nהיא צפויה להגיע אליך בין [from] ל־[to].\nנעדכן אותך במייל ברגע שהיא יוצאת לדרך, כדי שתדע בדיוק איפה היא.",
		"We have received your order and we are already getting it ready.\nWe will email you the moment it is waiting for you at the branch.\nEverything you ordered is listed below." => "קיבלנו את ההזמנה שלך ואנחנו כבר מכינים אותה.\nנעדכן אותך במייל ברגע שהיא מחכה לך בסניף.\nכל מה שהזמנת מופיע למטה.",
		"We have refunded your order.\nThe money goes back the way it was paid, and it usually takes a few working days to show up.\nThe amount and the order are below." => "ביצענו החזר עבור ההזמנה שלך.\nהכסף חוזר באותו אמצעי שבו שולם, ובדרך כלל לוקח כמה ימי עסקים עד שהוא מופיע.\nהסכום ופרטי ההזמנה מופיעים למטה.",
		"We have your order, and it is waiting for the payment to come through.\nThe moment it does we will get it ready and email you when it is waiting at the branch.\nEverything you ordered is listed below." => "ההזמנה שלך אצלנו, והיא ממתינה לאישור התשלום.\nברגע שהוא יתקבל נכין אותה ונעדכן אותך במייל כשהיא מחכה לך בסניף.\nכל מה שהזמנת מופיע למטה.",
		"We have your order, and it is waiting for the payment to come through.\nThe moment it does we will start getting it ready and email you again.\nEverything you ordered is listed below." => "ההזמנה שלך אצלנו, והיא ממתינה לאישור התשלום.\nברגע שהוא יתקבל נתחיל להכין אותה ונעדכן אותך במייל.\nכל מה שהזמנת מופיע למטה.",
		"We sent a code to the phone ending %s." => "שלחנו קוד לטלפון שמסתיים ב-%s.",
		"We use cookies to run the shop, measure visits and show relevant offers." => "אנחנו משתמשים בעוגיות כדי להפעיל את החנות, למדוד ביקורים ולהציג הצעות רלוונטיות.",
		"We use cookies to run the shop, to understand how it is used and to show you relevant offers. You choose what to allow, and you can change your mind at any time." => "אנחנו משתמשים בעוגיות כדי להפעיל את החנות, להבין איך משתמשים בה ולהציג לך הצעות רלוונטיות. אתם בוחרים מה לאפשר, ואפשר לשנות את הבחירה בכל עת.",
		"WebP is the same picture at about a quarter of the weight. Every browser in use reads it." => "WebP הוא אותה תמונה בערך ברבע מהמשקל. כל הדפדפנים בשימוש קוראים אותו.",
		"Wednesday" => "רביעי",
		"Weekly report" => "דוח שבועי",
		"Weight" => "עובי",
		"Welcome to [shop]" => "ברוך הבא ל־[shop]",
		"What already follows the choice" => "מה כבר פועל לפי הבחירה",
		"What customers paid, including shipping and VAT, for paid orders and orders in hand." => "מה שהלקוחות שילמו, כולל משלוח ומע״מ, בהזמנות ששולמו ובטיפול.",
		"What did not become sales" => "מה לא הפך למכירה",
		"What happens under the cursor" => "מה קורה מתחת לסמן",
		"What is recorded" => "מה נרשם",
		"What is this block?" => "מה הבלוק הזה?",
		"What it lists" => "מה מוצג בו",
		"What people search for" => "מה מחפשים",
		"What people search for most" => "מה שהכי מחפשים",
		"What separates it from the header." => "מה שמפריד בינו לבין ההדר.",
		"What separates it from the page." => "מה שמפריד בינו לבין תוכן העמוד.",
		"What the colours mean" => "מה הצבעים אומרים",
		"What the image says, for screen readers." => "מה שהתמונה אומרת, עבור קוראי מסך.",
		"What to do now" => "מה כדאי לעשות עכשיו",
		"What would you like to say?" => "מה תרצו להגיד?",
		"Whatever is ticked is added together with the product itself." => "כל מה שמסומן יתווסף לסל יחד עם המוצר עצמו.",
		"Whatever suits the picture" => "לפי התמונה",
		"WhatsApp" => "וואטסאפ",
		"WhatsApp and email" => "וואטסאפ וגם אימייל",
		"WhatsApp group" => "קבוצת וואטסאפ",
		"WhatsApp message" => "הודעת וואטסאפ",
		"WhatsApp number" => "מספר וואטסאפ",
		"WhatsApp sender number" => "מספר השולח בוואטסאפ",
		"When" => "מתי",
		"When \"place order\" is pressed, WooCommerce creates an unpaid order and holds its stock for a while. A shopper who comes back from the payment page to add something to the cart is still holding that stock through their own order, and with one unit left WooCommerce refuses the new order: \"not enough in stock\". With this on, the earlier unpaid order of the same shopper is cancelled quietly (no e-mail) the moment the new one is created, and its hold is released. Works with every payment method, since it happens before payment." => "בלחיצה על \"שליחת הזמנה\" ווקומרס יוצר הזמנה שלא שולמה ומשריין לה מלאי לזמן מוגבל. לקוח שחוזר מעמוד התשלום כדי להוסיף משהו לסל עדיין מחזיק את המלאי הזה דרך ההזמנה שלו עצמו, וכשנשארה יחידה אחת ווקומרס מסרב להזמנה החדשה: \"אין מספיק במלאי\". כשזה פעיל, ההזמנה הקודמת שלא שולמה של אותו לקוח מבוטלת בשקט (בלי מייל) ברגע שהחדשה נוצרת, והשריון שלה משתחרר. עובד עם כל שיטת תשלום, כי זה קורה לפני התשלום.",
		"When nothing matches" => "כשאין תוצאות",
		"When several prices apply" => "כשכמה מחירים חלים",
		"When the picture is taller than the tile it fills, this decides which part stays: 0 keeps the top (a head, a hat), 100 keeps the bottom." => "כשהתמונה גבוהה מהאריח שהיא ממלאת, זה קובע איזה חלק נשאר: 0 שומר על החלק העליון (ראש, כובע), 100 על החלק התחתון.",
		"When the search opens" => "כשהחיפוש נפתח",
		"Where" => "היכן",
		"Where it is used" => "איפה בשימוש",
		"Where orders came from" => "מאיפה הגיעו ההזמנות",
		"Where people look, and where they click. Only the pages below are recorded, and the visitor pays nothing for it: the marks are counted in the browser and sent once, as the page closes." => "איפה מסתכלים ואיפה לוחצים. רק העמודים שלמטה נרשמים, והגולש לא משלם על זה כלום: הסימונים נספרים בדפדפן ונשלחים פעם אחת, כשהעמוד נסגר.",
		"Where shoppers drop off" => "איפה הקונים נוטשים",
		"Where the face sits in the circle (0 = top, 100 = bottom)" => "איפה הפנים יושבות בעיגול (0 = למעלה, 100 = למטה)",
		"Where the panel opens from, its width, the footer buttons and the upsell placement are set in %s." => "מהיכן המגירה נפתחת, רוחבה, כפתורי התחתית ומיקום ההמלצות — נקבעים ב%s.",
		"Where the row lines up — also inside the banner. “Follow the text” keeps it with the banner’s words, or with the page title when it stands above the products." => "איפה השורה מתיישרת — גם בתוך הבאנר. ״לפי הטקסט״ מיישר אותה עם הטקסט של הבאנר, או עם כותרת העמוד כשהיא מעל המוצרים.",
		"Where the words sit" => "מיקום הטקסט",
		"Where they appear" => "היכן מוצגות",
		"Where they came from" => "מאיפה הגיעו",
		"Where this link appears" => "היכן הקישור מופיע",
		"Where to look" => "איפה מחפשים",
		"Whether filtering is on, its layout and how values are presented are set in %s." => "הפעלת הסינון, הפריסה שלו ואופן הצגת הערכים — נקבעים ב%s.",
		"Which brands" => "אילו מותגים",
		"Which built-in tabs appear, and in what order, is set in %s." => "אילו טאבים מובנים מוצגים ובאיזה סדר — נקבע ב%s.",
		"Which of its products" => "אילו מהמוצרים שלה",
		"Which part the frame keeps when it has to crop: 0 the top, 50 the middle, 100 the bottom." => "איזה חלק המסגרת שומרת כשהיא נאלצת לחתוך: 0 החלק העליון, 50 האמצע, 100 התחתון.",
		"Which pictures and films weigh the most, and which pages they sit on. A heavy file is not a mistake — it is simply what every visitor to that page downloads." => "אילו תמונות וסרטונים שוקלים הכי הרבה, ובאילו עמודים הם יושבים. קובץ כבד אינו טעות — הוא פשוט מה שכל מבקר בעמוד הזה מוריד.",
		"Which products" => "אילו מוצרים",
		"Which products count as similar" => "אילו מוצרים נחשבים דומים",
		"While you are searching, the order cannot be changed. Clear the box to go back to it." => "בזמן חיפוש אי אפשר לשנות את הסדר. נקו את תיבת החיפוש כדי לחזור אליו.",
		"White" => "לבן",
		"Who answers" => "מי עונה",
		"Who is it for?" => "למי הפיד?",
		"Whole keeps every product photo complete inside the box, with a quiet ground where its proportions differ from the ratio above." => "שלמה שומרת כל תמונת מוצר שלמה בתוך התיבה, עם רקע שקט היכן שהיחס שלה שונה מהיחס שלמעלה.",
		"Whole library" => "כל הספרייה",
		"Whole site" => "כל האתר",
		"Whole, never cropped" => "שלמה, בלי חיתוך",
		"Wide" => "רחב",
		"Wide content" => "תוכן רחב",
		"Wide gallery" => "גלריה רחבה",
		"Wide tile" => "אריח רחב",
		"Wide tile — every" => "אריח רחב — כל",
		"Wide — 2 columns" => "רחב — 2 עמודות",
		"Wide, with the words" => "רחב, עם הטקסט",
		"Width" => "רוחב",
		"Width (px)" => "רוחב (פיקסלים)",
		"With a comment, last 30 days" => "עם מילים, 30 יום אחרונים",
		"With the text, under the description" => "יחד עם הטקסט, מתחת לתיאור",
		"With you" => "אצלך",
		"Without a number there is nowhere to send a code, so this account still rests on its password alone." => "בלי מספר אין לאן לשלוח קוד, ולכן החשבון הזה עדיין מוגן בסיסמא בלבד.",
		"WooCommerce cart and session cookies, sign-in — necessary, always on." => "עוגיות הסל וה-session של WooCommerce, התחברות - הכרחיות, תמיד פעילות.",
		"WooCommerce holds stock for %1\$d minutes per unpaid order (%2\$s)." => "ווקומרס משריין מלאי למשך %1\$d דקות לכל הזמנה שלא שולמה (%2\$s).",
		"WooCommerce prices delivery again; %d of its methods were switched back on." => "ווקומרס מתמחרת שוב את המשלוח; %d משיטותיה הופעלו מחדש.",
		"WooCommerce → Settings → Products → Inventory" => "ווקומרס ← הגדרות ← מוצרים ← מלאי",
		"WooCommerce's own catalogue settings, and the theme's on top of them." => "הגדרות הקטלוג של ווקומרס עצמו, ושל התבנית מעליהן.",
		"WordPress did not produce a WebP file." => "וורדפרס לא יצר קובץ WebP.",
		"WordPress reviews never render as a tab — a dedicated mechanism replaces them." => "חוות הדעת של וורדפרס לא מוצגות כטאב — מנגנון ייעודי יחליף אותן.",
		"Wording" => "נוסח",
		"Words" => "טקסט",
		"Words held" => "מילים שמורות",
		"Words separated by commas — a nickname, a former name, the English spelling." => "מילים מופרדות בפסיקים — כינוי, שם קודם, או הכתיב הלועזי.",
		"Words separated by commas. A shopper who types any of them finds everything carrying this one — so on the colour red, write: אדומה, אדומים, אדומות." => "מילים מופרדות בפסיקים. מי שיקליד אחת מהן ימצא את כל מה שנושא את הערך הזה — למשל על הצבע אדום, כתבו: אדומה, אדומים, אדומות.",
		"Words that mean the same thing" => "מילים שמשמעותן זהה",
		"Worked out from your address" => "מחושב לפי הכתובת",
		"Working…" => "עובד…",
		"Worth doing now" => "כדאי לעשות עכשיו",
		"Wrapped rows" => "שורות שנשברות",
		"Write a privacy policy page for this site" => "כתיבת עמוד מדיניות פרטיות לאתר הזה",
		"Write the ALT into the library the moment a file is uploaded" => "קבע את ה-ALT בספרייה ברגע העלאת הקובץ",
		"Write your comment to the post here…" => "רשמו כאן את התגובה שלכם לפוסט…",
		"Written into the chat before the shopper sends. [product] becomes the product name and [link] its address. Empty: \"Hi, I'd like some help with [product] / Link: [link]\"." => "נכתבת בצ׳אט לפני שהלקוח שולח. [product] הופך לשם המוצר ו־[link] לכתובת שלו. אפשר גם [שם המוצר] ו־[קישור]. ריק: ״היי, אני מעוניין לקבל עזרה על מוצר [product] / קישור: [link]״.",
		"Wrong tries before the code dies" => "טעויות עד שהקוד נפסל",
		"XML" => "XML",
		"Yes" => "כן",
		"Yesterday" => "אתמול",
		"Yoast SEO is active, so the theme's own SEO engine stepped aside — two engines would print two title tags. Deactivate Yoast (after migrating in Settings ← SEO ← Tools) to switch over." => "Yoast SEO פעיל, ולכן מנוע ה-SEO של התבנית זז הצידה — שני מנועים ידפיסו שני תגי title. כבו את Yoast (אחרי מיגרציה בהגדרות ← SEO ← ייבוא וכלים) כדי לעבור.",
		"Yom Kippur" => "יום כיפור",
		"You already have items in your cart" => "כבר יש לך מוצרים בסל",
		"You are already signed up for one of the options" => "נרשמת כבר לאחת מהאפשרויות",
		"You are on the list — we will email you the moment it is back." => "נרשמת! נשלח לך מייל ברגע שהמוצר יחזור למלאי.",
		"You are on the list — we will let you know the moment it is back." => "נרשמת! נעדכן אותך ברגע שהמוצר חוזר למלאי.",
		"You are receiving this email because a password reset was asked for on your account at %s." => "קיבלת את המייל הזה כי התבקש איפוס סיסמה לחשבון שלך ב־%s.",
		"You are receiving this email because an account was opened at %s." => "קיבלת את המייל הזה כי נפתח חשבון ב־%s.",
		"You are receiving this email because an order was placed at %s." => "קיבלת את המייל הזה בעקבות הזמנה שבוצעה ב־%s.",
		"You are receiving this email because you asked %s to tell you when this came back." => "קיבלת את המייל הזה כי ביקשת מ־%s לעדכן אותך כשהמוצר יחזור למלאי.",
		"You are signed up for an update" => "נרשמת לקבלת עדכון",
		"You are signed up for an update on this product." => "נרשמת לקבלת עדכון על המוצר הזה.",
		"You asked us to let you know when %s returns to stock." => "ביקשת שנעדכן אותך כשהמוצר %s יחזור למלאי.",
		"You asked us to tell you when %s came back — it is here." => "ביקשת שנעדכן אותך כשהוא יחזור — %s חזר למלאי.",
		"You can also sign in with…" => "אפשר להתחבר גם עם...",
		"You cannot print orders." => "אין לך הרשאה להדפיס הזמנות.",
		"You earned free shipping!" => "מגיע לך משלוח חינם!",
		"You have signed out — see you soon" => "התנתקת מהחשבון — נתראה בקרוב",
		"You may also like" => "אולי יעניין אותך גם",
		"You save %s" => "חסכון של %s",
		"You saved %s" => "חסכת %s",
		"YouTube embeds use the no-cookie player" => "סרטוני YouTube מוטמעים בנגן ללא עוגיות",
		"Your buyers buy most on %1\$s between %2\$02d:00 and %3\$02d:00" => "הקונים שלכם קונים הכי הרבה ב‑%1\$s בין %2\$02d:00 ל‑%3\$02d:00",
		"Your cart is empty" => "סל הקניות שלך ריק",
		"Your comment could not be posted." => "לא הצלחנו לפרסם את התגובה.",
		"Your details" => "פרטי המזמין",
		"Your email" => "האימייל שלך",
		"Your email address" => "כתובת המייל שלך",
